 if(trace!=120)return 5;
 Choices<int>::Item<int>a{{1}};Choices<int>::Item<char*>b{{1,2}};Choices<int>::Item<int*>c{{1,2,3}};
 Choices<bool>::Item<int>d{4};
 if(a.tag()!=1||b.tag()!=2||c.tag()!=3||d.tag()!=4)return 6;
