 ++Same::count;
 if(Choices<int>::Item<int*>::count!=31||Choices<int>::Item<char*>::count!=20||Choices<bool>::Item<int>::count!=40)return 10;
 Levels<1>::Inner<2>first;Levels<2>::Inner<1>second;
