TEST_F(TranslateTest, CoreV2StaticRecordsPreserveStateAndSelfAddresses) {
  const auto Source = tmpFile("static-record-runtime.cpp");
  const auto Output = tmpFile("static-record-runtime.nc");
  writeFile(Source, R"cpp(struct R{int n;int data[2];int*p;};
R zero;
R value{3,{4,5},&value.n};
R array[2];
constexpr R seed{6,{7,8},nullptr};
R copied=seed;
R&alias=value;
struct Self{int n;int*p;constexpr Self():n(9),p(&n){}};
Self self;
constexpr Self readonly;
Self duplicate=readonly;
R&local(){static R r{10,{11,12},&r.n};return r;}
Self&localSelf(){static Self r;return r;}
int effects=0,drops=0;
struct Holder{inline static R object{13,{14,15},nullptr};~Holder(){++drops;}};
Holder&receiver(Holder&h){++effects;return h;}
R&temporary(){return Holder{}.object;}
template<int N>R&slot(){static R r{N,{0,0},&r.n};return r;}
template<int N>struct Store{inline static R object{N,{0,0},nullptr};};
template<int N>inline R object{N,{0,0},nullptr};
int main(){
 if(zero.n||zero.data[1]||zero.p||array[1].n||array[1].p)return 1;
 if(value.n!=3||value.data[1]!=5||value.p!=&value.n)return 2;
 *value.p=16;alias.data[0]=17;if(value.n!=16||value.data[0]!=17)return 3;
 if(copied.n!=6||copied.data[1]!=8||copied.p)return 4;
 copied.n=18;if(seed.n!=6||copied.n!=18)return 5;
 if(self.p!=&self.n||*self.p!=9)return 6;
 *self.p=19;if(self.n!=19||*readonly.p!=9)return 7;
 if(duplicate.p!=readonly.p||duplicate.p==&duplicate.n)return 8;
 R*p=&local();*p->p=20;p->data[1]=21;if(&local()!=p||local().n!=20||local().data[1]!=21)return 9;
 Self*s=&localSelf();*s->p=22;if(&localSelf()!=s||localSelf().n!=22||localSelf().p!=&s->n)return 10;
 {Holder h;receiver(h).object.n=23;if(effects!=1||Holder::object.n!=23)return 11;}
 temporary().n=24;if(drops!=2||Holder::object.n!=24)return 12;
 slot<3>().n=25;if(slot<3>().n!=25||slot<5>().n!=5||slot<3>().p!=&slot<3>().n)return 13;
 Store<3>::object.n=26;if(Store<3>::object.n!=26||Store<5>::object.n!=5)return 14;
 object<3>.n=27;if(object<3>.n!=27||object<5>.n!=5)return 15;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("static-record-runtime" + Optimization);
    auto Build = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Build.exitCode, 0) << Build.out << Build.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

