TEST_F(TranslateTest, CoreV2StaticPointersAcceptSourceComposition) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"global-null-zero", "int*p;bool f(){return p==nullptr;}"},
      {"global-null-explicit", "int*p=nullptr;int*q=0;bool f(){return p==q;}"},
      {"global-address", "int n=3;int*p=&n;int f(){return ++*p;}"},
      {"global-const-pointer", "int n=3;int*const p=&n;int f(){return ++*p;}"},
      {"global-const-pointee", "const int n=3;const int*p=&n;int f(){return *p;}"},
      {"global-string", "const char*p=\"hello\";int f(){return p[1];}"},
      {"global-string-end", "const char*p=\"abc\"+4;char f(){return p[-2];}"},
      {"global-string-reference-address", "const char(*p)[4]=&\"abc\";char f(){return (*p)[1];}"},
      {"global-array-decay", "int a[3]={1,2,3};int*p=a;int f(){return p[2];}"},
      {"global-array-offset", "int a[3]={1,2,3};int*p=a+1;int f(){return p[-1];}"},
      {"global-array-end", "int a[3]={1,2,3};int*p=a+3;int f(){return p[-1];}"},
      {"global-object-end", "int n=3;int*p=&n+1;int f(){return p[-1];}"},
      {"global-array-object-end", "int a[3]={1,2,3};int(*p)[3]=&a+1;int f(){return p[-1][2];}"},
      {"global-nested-array", "int a[2][3]={{1,2,3},{4,5,6}};int*p=&a[1][2];int f(){return *p;}"},
      {"global-row", "int a[2][3]={{1,2,3},{4,5,6}};int(*p)[3]=a+1;int f(){return (*p)[1];}"},
      {"global-const-record-field", "struct R{int n;};constexpr R r{3};const int*p=&r.n;int f(){return *p;}"},
      {"global-mutable-record-array-field", "struct R{int n;};R a[2]={{1},{2}};int*p=&a[1].n;int f(){return ++*p;}"},
      {"global-record-field-array", "struct R{char label[4];int a[2];};constexpr R r{\"cat\",{3,4}};const int*p=r.a+1;int f(){return *p;}"},
      {"global-const-member", "struct R{const int key;int n;};R a[2]={{1,2},{3,4}};const int*p=&a[1].key;int f(){return *p;}"},
      {"global-pointer-address", "int n;int*p=&n;int**q=&p;int f(){return **q;}"},
      {"global-pointer-self", "void*p=&p;bool f(){return p==&p;}"},
      {"global-void-conversion", "int n=3;void*p=&n;int f(){return *static_cast<int*>(p);}"},
      {"global-cv-conversion", "int n=3;constexpr const int*q=&n;int*p=const_cast<int*>(q);int f(){return ++*p;}"},
      {"global-constexpr-pointer-load", "int a[2]={1,2};constexpr int*q=a;int*p=q+1;int f(){return *p;}"},
      {"global-constexpr-function", "int n=3;constexpr int*get(){return &n;}int*p=get();int f(){return *p;}"},
      {"global-forward", "extern int n;int*p=&n;int n=3;int f(){return *p;}"},
      {"global-redeclaration", "int n=3;extern int*p;int*p=&n;extern int*p;int f(){return *p;}"},
      {"global-const-redeclaration", "int n=3;extern int*const p;int*const p=&n;int f(){return *p;}"},
      {"global-pointer-array", "int n=3;int*p[3]={&n,nullptr};int f(){return *p[0];}"},
      {"global-string-table", "const char*text[3]={\"one\",\"two\",nullptr};char f(){return text[1][0];}"},
      {"global-record-pointer-array", "int n=3;struct R{int*p;};R a[2]={{&n},{nullptr}};int f(){return *a[0].p;}"},
      {"global-const-record-pointer", "int n=3;struct R{int*p;};const R r{&n};int f(){return ++*r.p;}"},
      {"global-utf16", "const char16_t*p=u\"\\U0001f600\";char16_t f(){return p[1];}"},
      {"global-float-pointer", "float a[2]={1.25f,2.5f};float*p=a+1;float f(){return *p;}"},
      {"global-nullptr-address", "using N=decltype(nullptr);N n;N*p=&n;bool f(){return *p==nullptr;}"},
      {"global-callback-address", "int f(){return 3;}using F=int(*)();F target=f;F*p=&target;int g(){return (*p)();}"},
      {"local-static-null", "int*f(){static int*p;return p;}"},
      {"local-static-address", "int n=3;int*f(){static int*p=&n;return p;}"},
      {"local-static-string", "const char*f(){static const char*p=\"hello\";return p;}"},
      {"local-static-const", "int n=3;int*f(){static int*const p=&n;return p;}"},
      {"local-static-to-static", "int*f(){static int a[3]={1,2,3};static int*p=a+1;return p;}"},
      {"local-static-pointer-array", "int n=3;int**f(){static int*p[2]={&n,nullptr};return p;}"},
      {"local-static-template", "template<int N>int*f(){static int a[2]={N,0};static int*p=a;return p;}int*g(){return f<3>();}"},
      {"member-inline", "int n=3;struct R{inline static int*p=&n;};int f(){return *R::p;}"},
      {"member-outline", "int n=3;struct R{static int*p;};int*R::p=&n;int f(){return *R::p;}"},
      {"member-own-array", "struct R{inline static int a[2]={1,2};inline static int*p=a+1;};int f(){return *R::p;}"},
      {"member-constexpr-string", "struct R{inline static constexpr const char*p=\"cat\";};char f(){return R::p[1];}"},
      {"member-temporary", "int n=3,drops;struct R{inline static int*p=&n;~R(){++drops;}};int*f(){return R{}.p;}"},
      {"member-class-template", "template<int N>struct R{inline static int a[2]={N,0};inline static int*p=a;};int*f(){return R<3>::p;}"},
      {"member-class-outline", "int n=3;template<class T>struct R{static T*p;};template<class T>T*R<T>::p=&n;int*f(){return R<int>::p;}"},
      {"variable-template", "int n=3;template<class T>inline T*p=&n;int*f(){return p<int>;}"},
      {"variable-template-auto", "int n=3;template<class T>inline auto p=&n;int*f(){return p<int>;}"},
      {"variable-template-partial", "int a=3,b=4;template<class T>inline int*p=&a;template<class T>inline int*p<T*> =&b;int*f(){return p<int*>;}"},
      {"variable-template-full", "int a=3,b=4;template<class T>inline int*p=&a;template<>inline int*p<int> =&b;int*f(){return p<int>;}"},
      {"variable-template-own-array", "template<int N>inline int a[2]={N,0};template<int N>inline int*p=a<N>;int*f(){return p<3>;}"},
      {"member-variable-template", "int n=3;struct R{template<class T>inline static T*p=&n;};int*f(){return R::p<int>;}"},
      {"member-variable-outline", "int n=3;struct R{template<class T>static T*p;};template<class T>T*R::p=&n;int*f(){return R::p<int>;}"},
      {"promoted-1", "int*value=nullptr;"},
      {"promoted-2", "struct R{inline static int*n=nullptr;};"},
      {"promoted-3", "int*f(){static int*n=nullptr;return n;}"},
      {"promoted-4", "struct R{template<class T>inline static T*n=nullptr;};int main(){return R::n<int> == nullptr;}"},
      {"promoted-5", "int*a[2]={nullptr,nullptr};"},
      {"promoted-6", "int**f(){static int*a[2];return a;}"},
      {"promoted-7", "struct R{int*p;};R a[2]{};"},
      {"promoted-8", "const char*p=\"abc\";"},
      {"promoted-9", "int n=3;int*p=&n;int main(){return *p;}"},
      {"promoted-10", "int n=3;template<class T>int*p=&n;int main(){return *p<int>;}"},
      {"promoted-11", "template<class T>constexpr T*value=nullptr;int main(){return value<int> == nullptr;}"},
      {"promoted-12", "template<class T>struct R{inline static T*p=nullptr;};"},
      {"promoted-13", "template<class T>struct R{static T n;};static_assert(sizeof(R<int*>)==1);"},
      {"promoted-14", "static_assert(true,\"message\"); const char *s=\"runtime\"; int main(){}"},
      {"promoted-native-string", "static_assert(true, \"message\"); const char *value = \"runtime\";"},
      {"protocol-source", "extern int target;\nint*forward=&target;\nint target=3;\nint values[3]={1,2,3};\nint*end=values+3;\nconst char*literal=\"cat\";\nstruct Row{int values[2];};\nRow rows[2]={{{4,5}},{{6,7}}};\nint*nested=&rows[1].values[1];\nint**address=&forward;\nint*zero;\nint*local(){static int*p=&target;return p;}\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("static-pointer-positive-" + Name + ".cpp");
    const auto Output = tmpFile("static-pointer-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2StaticPointersRetainConstantAddressAndSourceRequirements) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"global-heap", "int*p=new int(3);", "TR0203"},
      {"global-integer-address", "int*p=reinterpret_cast<int*>(1);", "TR0201"},
      {"global-past-extent", "int a[2];int*p=a+3;", "TR0201"},
      {"global-before-array", "int a[2];int*p=a-1;", "TR0201"},
      {"global-past-object", "int n;int*p=&n+2;", "TR0201"},
      {"global-null-offset", "int*p=static_cast<int*>(nullptr)+1;", "TR0201"},
      {"global-tls", "int n;thread_local int*p=&n;", "TR0201"},
      {"local-tls-target", "int*f(){thread_local int n;static int*p=&n;return p;}", "TR0201"},
      {"member-volatile", "struct R{inline static int*volatile p=nullptr;};", "TR0201"},
      {"unsupported-pointee", "long double*p=nullptr;", "TR0201"},
      {"hidden-bound", "int a[2];int(*p)[(sizeof(long double),2)]=&a;", "TR0201"},
      {"hidden-initializer", "int n;int*p=(static_cast<void>(1.0L),&n);", "TR0201"},
      {"hidden-template-type", "template<class T>using I=int;int n;template<class T>I<decltype(T{}+1.0L)>*p=&n;int*f(){return p<int>;}", "TR0201"},
      {"pointer-nontype", "int n;template<int*P>int f(){return *P;}int g(){return f<&n>();}", "TR0201"},
      {"global-missing-pointee", "extern int n;int*p=&n;", "TR0203"},
      {"global-missing-pointer", "extern int*p;int*f(){return p;}", "TR0203"},
      {"global-missing-const-pointer", "extern int*const p;int*f(){return p;}", "TR0203"},
      {"member-missing-pointer", "struct R{static const int*n;};", "TR0203"},
      {"global-const-write", "const int n=3;const int*p=&n;void f(){*p=4;}", "TR0202"},
      {"global-const-reseat", "int n;int*const p=&n;void f(){p=nullptr;}", "TR0202"},
      {"global-drop-const", "const int n=3;int*p=&n;", "TR0202"},
      {"global-string-drop-const", "char*p=\"hello\";", "TR0202"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("static-pointer-reject-" + Name + ".cpp");
    const auto Output = tmpFile("static-pointer-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, Diagnostic);
    expectNoArtifacts(Output);
  }
  const auto Source = tmpFile("static-pointer-v1.cpp");
  const auto Output = tmpFile("static-pointer-v1.nc");
  writeFile(Source, "int n=3;int*p=&n;");
  auto Result = translate(Source, {"--profile", "cpp-core-v1", "-o", Output.string()});
  expectCode(Result, "TR0201");
  expectNoArtifacts(Output);
}

TEST_F(TranslateTest, CoreV2StaticArraysPreservePersistentStateAndIdentity) {
  const auto Source = tmpFile("static-array-runtime.cpp");
  const auto Output = tmpFile("static-array-runtime.nc");
  writeFile(Source, R"cpp(int zero[3];
int grid[2][3]={{1},{2,3}};
char text[6]="abc";
struct Entry{char name[4];const int key;int value;};
Entry entries[2]={{"one",1,2},{"two",3,4}};
int effects=0,drops=0;
int answer(){return 7;}
using Callback=int(*)();
Callback callbacks[2]={answer,nullptr};
using Null=decltype(nullptr);
Null nulls[2];
float fractions[2]={1.25f,2.5f};
int*local(){static int a[3]={5,6};++a[0];return a;}
const char*localText(){static const char a[5]="stay";return a;}
int skipped(bool enter){if(enter){static int a[2]={7,8};return ++a[0];}return 0;}
int switched(int n){switch(n){case 0:static int a[2]={9,10};return ++a[0];default:return 0;}}
struct Holder{
 inline static int data[2]={11,12};
 inline static constexpr char name[4]="key";
 ~Holder(){++drops;}
};
Holder&receiver(Holder&r){++effects;return r;}
int*temporary(){return Holder{}.data;}
template<int N>int*slot(){static int a[2]={N,0};return a;}
template<class T,int N>struct Store{inline static T data[2]={N,0};};
template<int N>inline int variable[2]={N,0};
struct MemberVariables{template<int N>inline static int data[2]={N,0};};
struct Outline{static int data[2];};
int Outline::data[2]={13,14};
int main(){
 if(zero[0]!=0||zero[2]!=0)return 1;
 zero[1]=3;if(zero[1]!=3||zero[2]!=0)return 2;
 grid[1][2]=4;if(grid[0][2]!=0||grid[1][2]!=4)return 3;
 text[0]='A';if(text[0]!='A'||text[3]!=0||text[5]!=0)return 4;
 entries[1].name[0]='T';entries[1].value=8;
 if(entries[0].name[0]!='o'||entries[1].name[0]!='T'||entries[1].key!=3||entries[1].value!=8)return 5;
 callbacks[1]=answer;if(callbacks[0]()!=7||callbacks[1]()!=7)return 6;
 if(nulls[0]!=nullptr||nulls[1]!=nullptr)return 7;
 fractions[1]+=0.5f;if(fractions[0]!=1.25f||fractions[1]!=3.0f)return 8;
 int*p=local();if(p[0]!=6||p[1]!=6||p[2]!=0)return 9;
 if(local()!=p||p[0]!=7)return 10;
 if(localText()!=localText()||localText()[3]!='y')return 11;
 if(skipped(false)!=0||skipped(true)!=8||skipped(true)!=9)return 12;
 if(switched(1)!=0||switched(0)!=10||switched(0)!=11)return 13;
 {Holder h;receiver(h).data[0]+=1;if(effects!=1||Holder::data[0]!=12)return 14;}
 if(drops!=1)return 15;
 int*q=temporary();if(drops!=2||q!=Holder::data||q[1]!=12)return 16;
 if(Holder::name[0]!='k'||Holder::name[3]!=0)return 17;
 int*s=slot<3>();s[1]=4;if(s!=slot<3>()||slot<3>()[1]!=4||slot<5>()[1]!=0)return 18;
 Store<int,3>::data[1]=6;if(Store<int,3>::data[1]!=6||Store<int,5>::data[1]!=0)return 19;
 variable<3>[1]=7;if(variable<3>[1]!=7||variable<5>[1]!=0||variable<3> == variable<5>)return 20;
 MemberVariables::data<3>[1]=8;if(MemberVariables::data<3>[1]!=8||MemberVariables::data<5>[1]!=0)return 21;
 Outline::data[0]+=1;if(Outline::data[0]!=14||Outline::data[1]!=14)return 22;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("static-array-runtime" + Optimization);
    auto Build = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Build.exitCode, 0) << Build.out << Build.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2StaticArraysAcceptSourceComposition) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"namespace-zero", "int a[3];int f(){return a[2];}"},
      {"namespace-initialized", "int a[3]={1,2};int f(){a[0]+=a[1];return a[0];}"},
      {"namespace-string", "char a[6]=\"abc\";char*f(){a[0]='A';return a;}"},
      {"namespace-nested", "int a[2][3]={{1},{2,3}};int f(){a[1][2]=4;return a[0][2];}"},
      {"namespace-redeclarations", "extern int a[2];int a[2]={1,2};extern int a[2];int*f(){return a;}"},
      {"namespace-reference", "int a[2]={1,2};int(&f())[2]{return a;}"},
      {"namespace-callback", "int f(){return 3;}using F=int(*)();F a[2]={f,nullptr};int g(){a[1]=f;return a[1]();}"},
      {"namespace-null-zero", "using N=decltype(nullptr);N a[2];bool f(){return a[1]==nullptr;}"},
      {"namespace-float", "float a[2]={1.25f,2.5f};float f(){a[1]+=0.5f;return a[1];}"},
      {"namespace-record", "struct R{char name[4];int n;};R a[2]={{\"one\",1},{\"two\",2}};int f(){a[1].n=4;return a[1].name[0];}"},
      {"namespace-const-field", "struct R{const int key;int n;};R a[2]={{1,2},{3,4}};int f(){a[0].n=5;return a[0].key;}"},
      {"namespace-constexpr-constructor", "struct R{int n;constexpr R(int v):n(v){}};R a[2]={R(1),R(2)};int f(){return ++a[0].n;}"},
      {"static-local-zero", "int*f(){static int a[3];++a[0];return a;}"},
      {"static-local-string", "char*f(){static char a[6]=\"abc\";a[0]='A';return a;}"},
      {"static-local-const", "const char*f(){static const char a[6]=\"abc\";return a;}"},
      {"static-local-nested", "int f(){static int a[2][2]={{1},{2,3}};return ++a[1][1];}"},
      {"static-local-record", "struct R{int n;};R*f(){static R a[2]={{1},{2}};return a;}"},
      {"static-local-branch", "int f(bool b){if(b){static int a[2]={1,2};return ++a[0];}return 0;}"},
      {"static-local-switch", "int f(int n){switch(n){case 0:static int a[2]={1,2};return ++a[0];default:return 0;}}"},
      {"static-local-loop", "int f(){for(int i=0;i<2;++i){static int a[2]={1,2};++a[0];if(i)return a[0];}return 0;}"},
      {"static-local-template", "template<int N>int*f(){static int a[2]={N,0};return a;}int*g(){return f<3>();}"},
      {"static-local-member", "struct R{int*f(){static int a[2]={1,2};return a;}};int g(){R a,b;return a.f()!=b.f();}"},
      {"member-inline", "struct R{inline static int a[2]={1,2};};int f(){return ++R::a[0];}"},
      {"member-outline", "struct R{static int a[2];};int R::a[2]={1,2};int*f(){return R::a;}"},
      {"member-zero", "struct R{static int a[2];};int R::a[2];int f(){return R::a[1];}"},
      {"member-const-outline", "struct R{static const int a[2];};const int R::a[2]={1,2};const int*f(){return R::a;}"},
      {"member-constexpr", "struct R{inline static constexpr char a[4]=\"cat\";};static_assert(R::a[1]=='a');const char*f(){return R::a;}"},
      {"member-receiver", "int calls;struct R{inline static int a[2]={1,2};};R&get(R&r){++calls;return r;}int f(){R r;get(r).a[0]+=3;return calls;}"},
      {"member-temporary-lifetime", "int drops;struct R{inline static int a[2]={1,2};~R(){++drops;}};int*f(){return R{}.a;}"},
      {"member-class-template", "template<class T,int N>struct R{inline static T a[N]={};};int*f(){return R<int,2>::a;}"},
      {"member-class-outline", "template<class T>struct R{static T a[2];};template<class T>T R<T>::a[2]={1,2};int*f(){return R<int>::a;}"},
      {"member-class-partial", "template<class T>struct R;template<class T>struct R<T*>{inline static T a[2]={1,2};};int*f(){return R<int*>::a;}"},
      {"member-class-specialization", "template<class T>struct R{inline static int a[2]={1,2};};template<>struct R<int>{inline static int a[2]={3,4};};int*f(){return R<int>::a;}"},
      {"variable-template", "template<int N>inline int a[2]={N,0};int*f(){return a<3>;}"},
      {"variable-template-type", "template<class T>inline T a[2]={};int*f(){return a<int>;}"},
      {"variable-template-const", "template<int N>inline constexpr int a[2]={N,0};static_assert(a<3>[0]==3);const int*f(){return a<3>;}"},
      {"variable-template-partial", "template<class T>inline int a[2]={1,2};template<class T>inline int a<T*>[2]={3,4};int*f(){return a<int*>;}"},
      {"variable-template-specialization", "template<class T>inline int a[2]={1,2};template<>inline int a<int>[2]={3,4};int*f(){return a<int>;}"},
      {"variable-template-explicit", "template<class T>int a[2]={1,2};template int a<int>[2];int*f(){return a<int>;}"},
      {"member-variable-template", "struct R{template<int N>inline static int a[2]={N,0};};int*f(){return R::a<3>;}"},
      {"member-variable-outline", "struct R{template<class T>static T a[2];};template<class T>T R::a[2]={1,2};int*f(){return R::a<int>;}"},
      {"aliases", "using A=int[2];A global{1,2};struct R{inline static A a{3,4};};int*f(){static A local{5,6};return local;}"},
      {"consteval-source-effects", "constexpr int value(){return 3;}int a[2]={value(),2};int f(){return a[0];}"},
      {"promoted-1", "int value[2]={1,2};"},
      {"promoted-2", "struct R{inline static int a[2]={1,2};};"},
      {"promoted-3", "int f(){static int n[2]={1,2};return n[0];}"},
      {"promoted-4", "struct R{template<class T>inline static int n[2]={1,2};};int main(){return R::n<int>[1];}"},
      {"promoted-5", "char a[]=\"abc\";"},
      {"promoted-6", "const char*f(){static const char a[]=\"abc\";return a;}"},
      {"promoted-7", "struct R{inline static constexpr char a[]=\"abc\";};"},
      {"promoted-8", "template<class T>int value[2]={1,2};int main(){return value<int>[1];}"},
      {"promoted-9", "template<class T>struct R{inline static T n[2]{};};"},
      {"promoted-10", "int a[2]={1,2};int f(int*p=a){return *p;}"},
      {"protocol-source", "int global[3];\nint initialized[3]={1,2};\nstruct Holder{\n inline static int data[2]={3,4};\n inline static constexpr char text[4]=\"cat\";\n};\nint*local(){static int data[2]={5,6};return data;}\ntemplate<int N>int*slot(){static int data[2]={N,0};return data;}\nint*one(){return slot<1>();}\nint*two(){return slot<2>();}\ntemplate<int N>inline int variable[2]={N,0};\nint*three(){return variable<3>;}\nint*four(){return variable<4>;}\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("static-array-positive-" + Name + ".cpp");
    const auto Output = tmpFile("static-array-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2StaticArraysRetainInitializationAndSourceRequirements) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"volatile-array", "volatile int a[2];", "TR0201"},
      {"tls-local", "int*f(){thread_local int a[2];return a;}", "TR0201"},
      {"tls-member", "struct R{inline static thread_local int a[2];};", "TR0201"},
      {"hidden-global-type", "int a[(sizeof(long double),2)]={1,2};", "TR0201"},
      {"hidden-template-bound", "template<class T>inline int a[(sizeof(long double),2)]={1,2};int*f(){return a<int>;}", "TR0201"},
      {"hidden-member-initializer", "struct R{inline static int a[2]={static_cast<int>(1.0L),2};};", "TR0201"},
      {"oversized-template", "template<int N>inline int a[N]{};int*f(){return a<65537>;}", "TR0201"},
      {"missing-global", "extern int a[2];int*f(){return a;}", "TR0203"},
      {"missing-member", "struct R{static int a[2];};int*f(){return R::a;}", "TR0203"},
      {"missing-const-member", "struct R{static const int n[2];};", "TR0203"},
      {"missing-variable-template", "template<class T>extern int a[2];int*f(){return a<int>;}", "TR0203"},
      {"const-local-write", "int f(){static const int a[2]={1,2};return ++a[0];}", "TR0202"},
      {"const-member-pointer", "struct R{inline static constexpr int a[2]={1,2};};int*f(){return R::a;}", "TR0202"},
      {"const-element-write", "struct R{const int n;};R a[2]={{1},{2}};void f(){a[0].n=3;}", "TR0202"},
      {"noninline-initializer", "struct R{static int a[2]={1,2};};", "TR0202"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("static-array-reject-" + Name + ".cpp");
    const auto Output = tmpFile("static-array-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, Diagnostic);
    expectNoArtifacts(Output);
  }
  const auto Source = tmpFile("static-array-v1.cpp");
  const auto Output = tmpFile("static-array-v1.nc");
  writeFile(Source, "int a[2]={1,2};");
  auto Result = translate(Source, {"--profile", "cpp-core-v1", "-o", Output.string()});
  expectCode(Result, "TR0201");
  expectNoArtifacts(Output);
}

TEST_F(TranslateTest, CoreV2StringsPreserveStaticStorageAndInitialization) {
  const auto Source = tmpFile("string-runtime.cpp");
  const auto Output = tmpFile("string-runtime.nc");
  writeFile(Source, R"cpp(int calls=0,drops=0;
const char table[6]="ab\0c";
constexpr int numbers[2][3]={{1,2},{3,4,5}};
struct Readonly{char name[4];int values[2];};
constexpr Readonly record{"key",{7,8}};
constexpr float fractions[2]={1.5f,2.5f};
constexpr char16_t utf16[]=u"\U0001f600";
constexpr char32_t utf32[]=U"\U0001f600";
const char*literal(){return "alive";}
const char(&reference())[6]{return "alive";}
const char*select(bool left){return left?(++calls,"left"):(calls+=2,"right");}
const char*defaulted(const char*p="default"){return p;}
template<class T>const char*templated(){return "template";}
int length(const char*p){int n=0;while(*p){++p;++n;}return n;}
struct Fields{char a[6]="field";char b[5]={"x"};};
struct Constructed{char a[4];Constructed():a("hey"){}};
struct Result{char a[4];};
Result make(){return {"cat"};}
struct Owner{char name[5]="drop";~Owner(){if(name[0]=='d')++drops;}};
struct Conversion{operator const char*()const{return "converted";}};
int answer(){return 17;}
using Callback=int(*)();
Callback const callbacks[2]={answer,nullptr};
int main(){
 const char*p=literal();
 if(p!=literal()||length(p)!=5||p[5]!=0)return 1;
 const char(&r)[6]=reference();
 if(&r!=&reference()||r[4]!='e')return 2;
 if(select(true)[0]!='l'||calls!=1||select(false)[0]!='r'||calls!=3)return 3;
 if(defaulted()!=defaulted()||length(defaulted())!=7)return 4;
 if(templated<int>()!=templated<int>()||templated<bool>()[0]!='t')return 5;
 char local[8]="hello";local[0]='H';
 if(local[0]!='H'||local[5]!=0||local[7]!=0||literal()[0]!='a')return 6;
 char braced[8]={"hi"};char parenthesized[8]=("ok");
 if(braced[1]!='i'||braced[7]!=0||parenthesized[1]!='k'||parenthesized[7]!=0)return 7;
 char embedded[]="a\0b";
 if(sizeof(embedded)!=4||embedded[1]!=0||embedded[2]!='b'||embedded[3]!=0)return 8;
 char adjacent[]="a" "b";char raw[]=R"tag(a\nb)tag";
 if(sizeof(adjacent)!=3||adjacent[1]!='b'||sizeof(raw)!=5||raw[1]!='\\'||raw[2]!='n')return 9;
 signed char signedBytes[]="\xff";unsigned char unsignedBytes[]="\xff";
 if(signedBytes[0]!=-1||unsignedBytes[0]!=255||signedBytes[1]!=0)return 10;
 const char*encoded=u8"\u00e9\U0001f600";
 if(static_cast<unsigned char>(encoded[0])!=0xc3||static_cast<unsigned char>(encoded[1])!=0xa9||static_cast<unsigned char>(encoded[2])!=0xf0||static_cast<unsigned char>(encoded[5])!=0x80||encoded[6]!=0)return 11;
 if(sizeof(utf16)!=6||utf16[0]!=0xd83d||utf16[1]!=0xde00||utf16[2]!=0)return 12;
 if(sizeof(utf32)!=8||utf32[0]!=0x1f600||utf32[1]!=0)return 13;
 wchar_t wide[]=L"\U0001f600";
 if(sizeof(wchar_t)==2){if(wide[0]!=0xd83d||wide[1]!=0xde00)return 14;}
 else{if(wide[0]!=0x1f600||wide[1]!=0)return 15;}
 int sum=0;for(char c:"ab")sum+=c;
 if(sum!='a'+'b')return 16;
 Fields fields;Constructed constructed;
 if(fields.a[4]!='d'||fields.a[5]!=0||fields.b[1]!=0||fields.b[4]!=0||constructed.a[2]!='y')return 17;
 char matrix[2][4]={"hi","ok"};matrix[0][0]='H';
 if(matrix[0][0]!='H'||matrix[0][3]!=0||matrix[1][1]!='k'||matrix[1][3]!=0)return 18;
 Result first=make();Result second(first);second.a[0]='b';
 if(first.a[0]!='c'||second.a[0]!='b'||&first.a[0]==&second.a[0])return 19;
 {Owner firstOwner;Owner secondOwner;}
 if(drops!=2)return 20;
 if(table[2]!=0||table[3]!='c'||table[4]!=0||table[5]!=0)return 21;
 if(numbers[0][2]!=0||numbers[1][2]!=5||record.name[2]!='y'||record.values[1]!=8)return 22;
 if(fractions[0]+fractions[1]!=4.0f)return 23;
 if(callbacks[0]()!=17||callbacks[1]!=nullptr)return 24;
 Conversion conversion;const char*converted=conversion;
 if(length(converted)!=9||converted[8]!='d')return 25;
 const char(&chosen)[4]=true?"yes":"nah";
 if(chosen[0]!='y'||chosen[3]!=0)return 26;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("string-runtime" + Optimization);
    auto Build = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Build.exitCode, 0) << Build.out << Build.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2StringsAcceptSourceComposition) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"literal-pointer", "const char*f(){return \"hello\";}"},
      {"literal-reference", "const char(&f())[6]{return \"hello\";}"},
      {"literal-address", "const char(*f())[6]{return &\"hello\";}"},
      {"literal-subscript", "char f(){return \"hello\"[1];}"},
      {"literal-offset", "const char*f(){return \"hello\"+2;}"},
      {"empty", "int f(){const char*p=\"\";return *p;}"},
      {"embedded-zero", "int f(){char a[]=\"a\\0b\";return sizeof(a)!=4||a[2]!=98;}"},
      {"adjacent", "int f(){char a[]=\"a\" \"b\";return sizeof(a)!=3||a[1]!=98;}"},
      {"raw", "int f(){char a[]=R\"tag(a\\nb)tag\";return sizeof(a)!=5||a[1]!=92;}"},
      {"zero-fill", "int f(){char a[8]=\"hi\";return a[7];}"},
      {"braced", "int f(){char a[8]={\"hi\"};return a[7];}"},
      {"parenthesized", "int f(){char a[8]=(\"hi\");return a[7];}"},
      {"signed-character", "int f(){signed char a[]=\"\\xff\";return a[0]!=-1;}"},
      {"unsigned-character", "int f(){unsigned char a[]=\"\\xff\";return a[0]!=255;}"},
      {"utf8", "int f(){auto&p=u8\"\\u00e9\";return sizeof(p)!=3||static_cast<unsigned char>(p[0])!=195;}"},
      {"utf16", "int f(){char16_t a[]=u\"\\U0001f600\";return sizeof(a)!=6||a[0]!=0xd83d;}"},
      {"utf32", "int f(){char32_t a[]=U\"\\U0001f600\";return sizeof(a)!=8||a[0]!=0x1f600;}"},
      {"wide", "int f(){wchar_t a[]=L\"abc\";return a[2]!=L'c';}"},
      {"range", "int f(){int n=0;for(char c:\"ab\")n+=c;return n-195;}"},
      {"range-reference", "int f(){const char*p=\"ab\";for(const char&c:\"ab\"){if(c)return c;}return *p;}"},
      {"conditional", "const char*f(bool b){return b?\"yes\":\"no\";}"},
      {"conditional-array", "const char(&f(bool b))[4]{return b?\"yes\":\"nah\";}"},
      {"comma", "int n;const char*f(){return (++n,\"hello\");}"},
      {"default", "const char*f(const char*p=\"default\"){return p;}"},
      {"template", "template<class T>const char*f(){return \"template\";}const char*g(){return f<int>();}"},
      {"template-array-deduction", "template<unsigned long long N>unsigned long long length(const char(&a)[N]){return N;}int f(){return length(\"abc\");}"},
      {"constructor-array", "struct R{char a[6];R():a(\"hello\"){}};int f(){R r;return r.a[1];}"},
      {"field-default", "struct R{char a[6]=\"hello\";};int f(){R r;return r.a[1];}"},
      {"braced-field-default", "struct R{char a[6]={\"hello\"};};int f(){R r;return r.a[1];}"},
      {"nested-array", "int f(){char a[2][4]={\"hi\",\"ok\"};return a[1][1];}"},
      {"aggregate-copy", "struct R{char a[4];};int f(){R r{\"cat\"};R s(r);s.a[0]='b';return r.a[0]!='c';}"},
      {"record-return", "struct R{char a[4];};R f(){return {\"cat\"};}int g(){return f().a[2];}"},
      {"literal-conversion", "struct R{operator const char*()const{return \"x\";}};"},
      {"discarded", "void f(){static_cast<void>(\"text\");}"},
      {"default-discarded", "int f(int n=(static_cast<void>(\"x\"),1)){return n;}"},
      {"unused-default-discarded", "int f(int n=(static_cast<void>(\"unused\"),1)){return n;}"},
      {"assertion", "static_assert(\"abc\"[1]=='b');static_assert(sizeof(\"abc\")==4);"},
      {"noexcept", "static_assert(noexcept(\"abc\"[1]));"},
      {"enum", "enum E:int{value=\"a\"[0]};int f(){return value;}"},
      {"constexpr-function", "constexpr int f(){return \"abc\"[2];}static_assert(f()=='c');"},
      {"const-global-string", "const char a[]=\"global\";const char*f(){return a;}"},
      {"constexpr-global-string", "constexpr char a[8]=\"global\";static_assert(a[7]==0);"},
      {"const-global-array", "const int a[2][3]={{1,2},{3,4,5}};int f(){return a[1][2];}"},
      {"const-global-record", "struct R{char a[4];int n[2];};constexpr R r{\"cat\",{1,2}};int f(){return r.a[2]+r.n[1];}"},
      {"const-global-record-array", "struct R{int n;};const R r[2]={{1},{2}};int f(){return r[1].n;}"},
      {"const-global-floating", "constexpr float a[2]={1.5f,2.5f};float f(){return a[1];}"},
      {"const-global-null", "using N=decltype(nullptr);constexpr N a[2]={nullptr,nullptr};bool f(){return a[1]==nullptr;}"},
      {"const-global-callback", "int f(){return 1;}using F=int(*)();F const a[2]={f,nullptr};int g(){return a[0]();}"},
      {"const-global-redeclaration", "extern const char a[4];const char a[4]=\"cat\";extern const char a[4];const char*f(){return a;}"},
      {"const-global-default", "constexpr char a[]=\"x\";char f(const char*p=a){return *p;}"},
      {"const-global-array-reference", "constexpr int a[2]={1,2};const int(&f())[2]{return a;}"},
      {"utf16-global", "constexpr char16_t a[]=u\"\\U0001f600\";char16_t f(){return a[1];}"},
      {"erased-literal-default", "template<int N=sizeof(\"abc\")>int f(){return N;}int g(){return f();}"},
      {"protocol-source", "const char global[6]=\"ab\\0c\";\nconst char*first(){return \"same\";}\nconst char(&reference())[5]{return \"wide\";}\nconst char16_t*wide(){return u\"\\U0001f600\";}\nint local(){char a[8]={\"x\"};return a[7];}\nint query(){return sizeof(\"query\");}\nvoid discarded(){void(\"discarded\");}\nconst int values[2][2]={{1},{2,3}};\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("string-positive-" + Name + ".cpp");
    const auto Output = tmpFile("string-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2CStringScansRunAtBothOptimizations) {
  const auto Source = tmpFile("cstring-scans.cpp");
  const auto Output = tmpFile("cstring-scans.nc");
  writeFile(Source, R"cpp(
#include <cstring>
int main() {
  const char high[3]{'A', static_cast<char>(0x80), 0};
  const char low[3]{'A', static_cast<char>(0x7f), 0};
  int effects = 0;
  if (std::strlen((++effects, high)) != 2 || effects != 1 ||
      std::strlen("") != 0 || std::strlen("hello") != 5)
    return 1;
  if (std::strcmp(high, low) <= 0 || std::strcmp(low, high) >= 0 ||
      std::strcmp(high, high) != 0 || std::strcmp("ab", "abc") >= 0 ||
      std::strcmp("abc", "ab") <= 0)
    return 2;
  effects = 0;
  if (std::strncmp(high, low, (++effects, 1)) != 0 || effects != 1 ||
      std::strncmp(high, low, 2) <= 0 ||
      std::strncmp("x", "y", 0) != 0 ||
      std::strncmp("abc", "abd", 2) != 0 ||
      std::strncmp("ab", "abc", 3) >= 0)
    return 3;
  const char embedded_left[4]{'x', 0, 'a', 'z'};
  const char embedded_right[4]{'x', 0, 'b', 'z'};
  int left_effects = 0, right_effects = 0, count_effects = 0;
  if (std::memcmp((++left_effects, embedded_left),
                  (++right_effects, embedded_right),
                  (++count_effects, 0)) != 0 ||
      left_effects != 1 || right_effects != 1 || count_effects != 1 ||
      std::memcmp(embedded_left, embedded_right, 2) != 0 ||
      std::memcmp(embedded_left, embedded_right, 4) >= 0 ||
      std::memcmp(embedded_right, embedded_left, 4) <= 0 ||
      std::memcmp(high, low, 2) <= 0)
    return 4;
  const int object = 42;
  if (std::memcmp(&object, &object, sizeof object) != 0)
    return 5;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *Dependencies =
      Manifest->getAsObject()->getObject("sdk")->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
  }
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("cstring-scans" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

