TEST_F(TranslateTest, CoreV2CallbackExchangeRunsAtBothOptimizations) {
  const auto Source = tmpFile("callback-exchange.cpp");
  const auto Output = tmpFile("callback-exchange.nc");
  writeFile(Source, R"cpp(
#include <utility>
int one(int value) { return value + 1; }
int two(int value) { return value + 2; }
int three(int value) noexcept { return value + 3; }
int four(int value) noexcept { return value + 4; }
using Callback = int (*)(int);
using NoexceptCallback = int (*)(int) noexcept;
namespace N {
struct Arg { int value; };
int one(Arg value) { return value.value + 1; }
int two(Arg value) { return value.value + 2; }
int three(Arg value) noexcept { return value.value + 3; }
using Callback = int (*)(Arg);
}
int main() {
  Callback first = one, second = two;
  int first_reads = 0, second_reads = 0;
  Callback old = std::exchange((++first_reads, first),
                               (++second_reads, second));
  if (first_reads != 1 || second_reads != 1 ||
      old(5) != 6 || first(5) != 7 || second(5) != 7)
    return 1;
  Callback previous = std::exchange(first, Callback{one});
  if (previous(5) != 7 || first(5) != 6)
    return 2;
  Callback self = std::exchange(first, first);
  if (self(5) != 6 || first(5) != 6)
    return 3;
  N::Callback left = N::one, right = N::two;
  N::Callback saved = std::exchange(left, right);
  if (saved(N::Arg{5}) != 6 || left(N::Arg{5}) != 7)
    return 4;
  Callback cleared = std::exchange(first, nullptr);
  if (cleared(5) != 6 || first != nullptr)
    return 5;
  first = two;
  decltype(nullptr) empty = nullptr;
  Callback cleared_again = std::exchange(first, empty);
  if (cleared_again(5) != 7 || first != nullptr)
    return 6;
  Callback empty_old = std::exchange(first, one);
  if (empty_old != nullptr || first(5) != 6)
    return 7;
  Callback function_old = std::exchange(first, two);
  if (function_old(5) != 6 || first(5) != 7)
    return 8;
  const Callback immutable = one;
  Callback const_old = std::exchange(first, immutable);
  if (const_old(5) != 7 || first(5) != 6 || immutable(5) != 6)
    return 9;
  const decltype(nullptr) const_empty = nullptr;
  Callback const_cleared = std::exchange(first, const_empty);
  if (const_cleared(5) != 6 || first != nullptr)
    return 10;
  Callback noexcept_old = std::exchange(first, three);
  if (noexcept_old != nullptr || first(5) != 8)
    return 11;
  NoexceptCallback replacement = four;
  Callback noexcept_pointer_old = std::exchange(first, replacement);
  if (noexcept_pointer_old(5) != 8 || first(5) != 9 ||
      replacement(5) != 9)
    return 12;
  Callback noexcept_temporary_old =
      std::exchange(first, NoexceptCallback{three});
  if (noexcept_temporary_old(5) != 9 || first(5) != 8)
    return 13;
  const NoexceptCallback const_replacement = four;
  Callback const_noexcept_old = std::exchange(first, const_replacement);
  if (const_noexcept_old(5) != 8 || first(5) != 9 ||
      const_replacement(5) != 9)
    return 14;
  N::Callback nested_old = std::exchange(left, nullptr);
  if (nested_old(N::Arg{5}) != 7 || left != nullptr)
    return 15;
  N::Callback nested_empty = std::exchange(left, N::one);
  const N::Callback nested_immutable = N::two;
  N::Callback nested_const_old = std::exchange(left, nested_immutable);
  const decltype(nullptr) nested_const_empty = nullptr;
  N::Callback nested_const_cleared = std::exchange(left, nested_const_empty);
  N::Callback nested_noexcept_old = std::exchange(left, N::three);
  return nested_empty == nullptr && nested_const_old(N::Arg{5}) == 6 &&
                 nested_const_cleared(N::Arg{5}) == 7 &&
                 nested_noexcept_old == nullptr && left(N::Arg{5}) == 8 &&
                 nested_immutable(N::Arg{5}) == 7
             ? 0
             : 16;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("callback-exchange" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2UtilityCompositePairsRunAtBothOptimizations) {
  const auto Source = tmpFile("utility-composite-pair.cpp");
  const auto Output = tmpFile("utility-composite-pair.nc");
  writeFile(Source, R"cpp(
#include <array>
#include <utility>
struct Point { int x; int y; };
int main() {
  using PointPair = std::pair<Point, int>;
  PointPair first{{1, 2}, 3};
  PointPair zero{};
  if (zero.first.x != 0 || zero.first.y != 0 || zero.second != 0)
    return 1;
  PointPair copied(first);
  PointPair moved(static_cast<PointPair &&>(copied));
  zero = moved;
  std::get<0>(zero).x = 4;
  std::get<Point>(zero).y = 5;
  auto made = std::make_pair(Point{6, 7}, 8);
  zero.swap(made);
  std::swap(zero, made);
  if (zero.first.x != 4 || zero.first.y != 5 || zero.second != 3 ||
      made.first.x != 6 || made.first.y != 7 || made.second != 8)
    return 2;

  using Inner = std::pair<int, int>;
  using Nested = std::pair<Inner, std::array<int, 2>>;
  Nested nested{{9, 10}, {{11, 12}}};
  Nested nestedCopy(nested);
  nestedCopy = nested;
  std::get<1>(std::get<0>(nestedCopy)) = 13;
  nested.swap(nestedCopy);
  std::swap(nested, nestedCopy);
  auto &values = std::get<std::array<int, 2>>(nested);
  if (nested.first.first != 9 || nested.first.second != 10 ||
      values[0] != 11 || values[1] != 12 ||
      nestedCopy.first.second != 13)
    return 3;
  return 0;
}
)cpp");
  auto Result = translate(
      Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest = llvm::json::parse(
      readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 222u);

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("utility-composite-pair" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

