TEST_F(TranslateTest, CoreV2TupleCatOwnedPairsPreserveConstructorDefaults) {
  const auto Source = tmpFile("tuple-cat-owned-pair-defaults.cpp");
  const auto Output = tmpFile("tuple-cat-owned-pair-defaults.nc");
  writeFile(Source, R"cpp(#include <array>
#include <functional>
#include <tuple>
#include <utility>
int live, defaults, drops, copies, moves, parameter_drops, bad, expected;
bool observing;
struct Guard {
  bool tracked;
  Guard() noexcept : tracked(observing) {
    ++live;
    if (tracked)
      ++defaults;
  }
  ~Guard() noexcept {
    --live;
    if (tracked)
      ++drops;
  }
};
struct Item {
  int value;
  explicit Item(int n) noexcept : value(n) {}
  Item(const Item &other, const Guard &guard = Guard{}) noexcept
      : value(other.value) {
    if (observing) {
      ++copies;
      if (live < 1 || live > expected)
        ++bad;
    }
  }
  Item(Item &&other, const Guard &guard = Guard{}) noexcept
      : value(other.value) {
    if (observing) {
      ++moves;
      if (live < 1 || live > expected)
        ++bad;
    }
  }
  ~Item() noexcept {
    if (observing && live)
      ++parameter_drops;
  }
  int combine(Item other) const noexcept {
    if (live != expected)
      ++bad;
    return value * 10 + other.value + live * 100;
  }
};
int consume(Item first, Item second) noexcept {
  if (live != expected)
    ++bad;
  return first.value * 10 + second.value + live * 100;
}
struct Reader {
  int operator()(Item first, Item second) const noexcept {
    if (live != expected)
      ++bad;
    return first.value * 10 + second.value + live * 100;
  }
};
struct Receiver {
  int consume(Item first, Item second) const noexcept {
    if (live != expected)
      ++bad;
    return first.value * 10 + second.value + live * 100;
  }
};
void reset(int n) noexcept {
  observing = true;
  expected = n;
  defaults = drops = copies = moves = parameter_drops = bad = 0;
}
bool valid(int count, int copy_count, int move_count) noexcept {
  return !bad && !live && defaults == count && drops == count &&
         copies == copy_count && moves == move_count &&
         parameter_drops == count;
}

int main() {
  std::pair<Item, Item> pair(Item(2), Item(3));
  reset(1);
  {
    auto copy = std::tuple_cat(pair);
    if (bad || live || defaults != 2 || drops != 2 || copies != 2 || moves ||
        parameter_drops || std::get<0>(copy).value != 2 ||
        std::get<1>(copy).value != 3)
      return 1;
    auto move = std::tuple_cat(std::move(pair));
    if (bad || live || defaults != 4 || drops != 4 || copies != 2 ||
        moves != 2 || parameter_drops || std::get<0>(move).value != 2 ||
        std::get<1>(move).value != 3)
      return 2;
  }
  observing = false;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("tuple-cat-owned-pair-defaults" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest,
       CoreV2InvokeEvaluatesCallerArgumentsBeforeParameterCopies) {
  const auto Source = tmpFile("invoke-caller-evaluation.cpp");
  const auto Output = tmpFile("invoke-caller-evaluation.nc");
  writeFile(Source, R"cpp(#include <array>
#include <functional>
#include <tuple>
#include <utility>
int live, defaults, drops, copies, moves, parameter_drops, bad, expected;
bool observing;
struct Guard {
  bool tracked;
  Guard() noexcept : tracked(observing) {
    ++live;
    if (tracked)
      ++defaults;
  }
  ~Guard() noexcept {
    --live;
    if (tracked)
      ++drops;
  }
};
struct Item {
  int value;
  explicit Item(int n) noexcept : value(n) {}
  Item(const Item &other, const Guard &guard = Guard{}) noexcept
      : value(other.value) {
    if (observing) {
      ++copies;
      if (live < 1 || live > expected)
        ++bad;
    }
  }
  Item(Item &&other, const Guard &guard = Guard{}) noexcept
      : value(other.value) {
    if (observing) {
      ++moves;
      if (live < 1 || live > expected)
        ++bad;
    }
  }
  ~Item() noexcept {
    if (observing && live)
      ++parameter_drops;
  }
  int combine(Item other) const noexcept {
    if (live != expected)
      ++bad;
    return value * 10 + other.value + live * 100;
  }
};
int consume(Item first, Item second) noexcept {
  if (live != expected)
    ++bad;
  return first.value * 10 + second.value + live * 100;
}
struct Reader {
  int operator()(Item first, Item second) const noexcept {
    if (live != expected)
      ++bad;
    return first.value * 10 + second.value + live * 100;
  }
};
struct Receiver {
  int consume(Item first, Item second) const noexcept {
    if (live != expected)
      ++bad;
    return first.value * 10 + second.value + live * 100;
  }
};
void reset(int n) noexcept {
  observing = true;
  expected = n;
  defaults = drops = copies = moves = parameter_drops = bad = 0;
}
bool valid(int count, int copy_count, int move_count) noexcept {
  return !bad && !live && defaults == count && drops == count &&
         copies == copy_count && moves == move_count &&
         parameter_drops == count;
}

int caller_reads;
int modify(Item &item) noexcept {
  ++caller_reads;
  item.value = 9;
  return 3;
}
int consume_one(Item item, int extra) noexcept {
  if (live != 1 || caller_reads != 1)
    ++bad;
  return item.value * 10 + extra + live * 100;
}
struct ReaderOne {
  int operator()(Item item, int extra) const noexcept {
    if (live != 1 || caller_reads != 1)
      ++bad;
    return item.value * 10 + extra + live * 100;
  }
  int read(Item item, int extra) const noexcept {
    if (live != 1 || caller_reads != 1)
      ++bad;
    return item.value * 10 + extra + live * 100;
  }
};
int main() {
  Item item(2);
  ReaderOne reader;
  auto function = std::ref(consume_one);
  auto object = std::cref(reader);
  auto member = std::mem_fn(&ReaderOne::read);
  reset(1);
  caller_reads = 0;
  if (std::invoke(consume_one, item, modify(item)) != 193 || !valid(1, 1, 0))
    return 1;
  reset(1);
  caller_reads = 0;
  item.value = 2;
  if (std::invoke(reader, item, modify(item)) != 193 || !valid(1, 1, 0))
    return 2;
  reset(1);
  caller_reads = 0;
  item.value = 2;
  if (std::invoke(function, item, modify(item)) != 193 || !valid(1, 1, 0))
    return 3;
  reset(1);
  caller_reads = 0;
  item.value = 2;
  if (std::invoke(&ReaderOne::read, reader, item, modify(item)) != 193 ||
      !valid(1, 1, 0))
    return 4;
  reset(1);
  caller_reads = 0;
  item.value = 2;
  if (object(item, modify(item)) != 193 || !valid(1, 1, 0))
    return 5;
  reset(1);
  caller_reads = 0;
  item.value = 2;
  if (member(reader, item, modify(item)) != 193 || !valid(1, 1, 0))
    return 6;
  observing = false;
  return item.value == 9 ? 0 : 7;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("invoke-caller-evaluation" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2InvocationCallbackConversionsNoexceptValues) {
  const auto Source = tmpFile("callback-conversion-noexcept-values.cpp");
  const auto Output = tmpFile("callback-conversion-noexcept-values.nc");
  writeFile(Source, R"cpp(#include <functional>
#include <tuple>
#include <utility>
using F = int (*)(int);
using N = int (*)(int) noexcept;
int safe(int n) noexcept { return n + 2; }
int consume(F f, int n) { return f ? f(n) : 9; }
int boolean(bool f, int n) { return f ? n : 9; }
struct Reader {
  int operator()(F f, int n) const { return consume(f,n); }
  int read(F f, int n) const { return consume(f,n); }
};
struct BooleanReader {
  int operator()(bool f, int n) const { return boolean(f,n); }
  int read(bool f, int n) const { return boolean(f,n); }
};
int main() { Reader reader;
N argument = safe;
if (std::invoke(consume, argument, 3) != 5) return 1;
if (std::invoke(reader, argument, 3) != 5) return 2;
if (std::invoke(&Reader::read, reader, argument, 3) != 5) return 3;
if (std::mem_fn(&Reader::read)(reader, argument, 3) != 5) return 4;
if (std::invoke(std::mem_fn(&Reader::read), reader, argument, 3) != 5) return 5;
if (std::ref(consume)(argument, 3) != 5) return 6;
if (std::invoke(std::ref(consume), argument, 3) != 5) return 7;
if (std::apply(consume, std::make_tuple(argument, 3)) != 5) return 8;
if (std::apply(reader, std::make_tuple(argument, 3)) != 5) return 9;
if (std::apply(std::ref(consume), std::make_tuple(argument, 3)) != 5) return 10;
if (std::apply(&Reader::read, std::make_tuple(std::ref(reader), argument, 3)) != 5) return 11;
if (std::apply(std::mem_fn(&Reader::read), std::make_tuple(std::ref(reader), argument, 3)) != 5) return 12;
return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("callback-conversion-noexcept-values" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

