TEST_F(TranslateTest, CoreV2EmptyTupleRunsAtBothOptimizations) {
  const auto Source = tmpFile("tuple-empty.cpp");
  const auto Output = tmpFile("tuple-empty.nc");
  writeFile(Source, R"cpp(
#include <tuple>
static_assert(std::tuple_size<std::tuple<>>::value == 0);
static_assert(sizeof(std::tuple<>) == 1);
static_assert(alignof(std::tuple<>) == 1);
int effects;
int trace;
std::tuple<> &touch(std::tuple<> &value, int mark) {
  ++effects;
  trace = trace * 10 + mark;
  return value;
}
std::tuple<> make_empty() {
  ++effects;
  return std::make_tuple();
}
int main() {
  std::tuple<> first;
  std::tuple<> copied(first);
  std::tuple<> moved(static_cast<std::tuple<> &&>(copied));

  effects = 0;
  trace = 0;
  touch(first, 1) = touch(copied, 2);
  if (effects != 2 || trace != 21)
    return 1;
  moved = static_cast<std::tuple<> &&>(copied);

  effects = 0;
  auto made = make_empty();
  if (effects != 1)
    return 2;
  auto direct = std::make_tuple();

  effects = 0;
  trace = 0;
  touch(first, 1).swap(touch(made, 2));
  if (effects != 2 || trace != 12)
    return 3;
  effects = 0;
  std::swap(touch(first, 1), touch(direct, 2));
  if (effects != 2)
    return 4;

  if (!(first == copied) || first != copied || first < copied ||
      first > copied || !(first <= copied) || !(first >= copied))
    return 5;
  effects = 0;
  if (!(touch(first, 1) == touch(copied, 2)) || effects != 2)
    return 6;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 98u);
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
  }

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("tuple-empty" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2TupleConvertsScalarPairs) {
  const auto Source = tmpFile("tuple-pair.cpp");
  const auto Output = tmpFile("tuple-pair.nc");
  writeFile(Source, R"cpp(
#include <tuple>
#include <utility>
int main() {
  int objects[2]{7, 9};
  std::pair<short, int *> source(short(12), objects + 1);
  std::tuple<int, const int *> copied(source);
  std::tuple<int, const int *> moved(
      static_cast<std::pair<short, int *> &&>(source));
  std::tuple<int, const int *> assigned;
  assigned = source;
  std::tuple<int, const int *> move_assigned;
  move_assigned = static_cast<std::pair<short, int *> &&>(source);
  if (std::get<int>(copied) != 12 ||
      std::get<const int *>(copied) != objects + 1 ||
      std::get<0>(moved) != 12 || std::get<1>(assigned) != objects + 1 ||
      std::get<0>(move_assigned) != 12)
    return 1;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 108u);
  bool FoundTuple = false, FoundUtility = false;
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
    FoundTuple |= Dependency->getString("root") == "libcxx" &&
                  Dependency->getString("path") == "tuple";
    FoundUtility |= Dependency->getString("root") == "libcxx" &&
                    Dependency->getString("path") == "utility";
  }
  EXPECT_TRUE(FoundTuple);
  EXPECT_TRUE(FoundUtility);

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("tuple-pair" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2TupleCompositeValuesRunAtBothOptimizations) {
  const auto Source = tmpFile("tuple-composite.cpp");
  const auto Output = tmpFile("tuple-composite.nc");
  writeFile(Source, R"cpp(
#include <array>
#include <tuple>
#include <utility>
struct Point { int x; int y; };
int main() {
  using Array = std::array<int, 2>;
  using Pair = std::pair<int, int>;
  using Value = std::tuple<Point, Array, Pair>;
  Value first(Point{1, 2}, Array{{3, 4}}, Pair{5, 6});
  Value zero{};
  if (std::get<Point>(zero).x != 0 || std::get<Array>(zero)[1] != 0 ||
      std::get<Pair>(zero).second != 0)
    return 1;
  Value copied(first);
  zero = copied;
  std::get<Point>(zero).x = 7;
  auto made = std::make_tuple(Point{8, 9}, Array{{10, 11}}, Pair{12, 13});
  zero.swap(made);
  std::swap(zero, made);
  if (std::get<Point>(zero).x != 7 || std::get<Point>(zero).y != 2 ||
      std::get<Array>(zero)[0] != 3 || std::get<Pair>(zero).second != 6 ||
      std::get<Point>(made).x != 8 || std::get<Array>(made)[1] != 11)
    return 2;

  using Nested = std::tuple<std::tuple<int, int>, Point>;
  Nested nested(std::tuple<int, int>{14, 15}, Point{16, 17});
  Nested other(nested);
  other = nested;
  nested.swap(other);
  std::swap(nested, other);
  if (std::get<0>(std::get<0>(nested)) != 14 ||
      std::get<1>(std::get<0>(nested)) != 15 ||
      std::get<Point>(nested).x != 16 || std::get<Point>(nested).y != 17)
    return 3;

  using Duo = std::tuple<Point, Array>;
  std::pair<Point, Array> source{Point{18, 19}, Array{{20, 21}}};
  Duo fromPair(source);
  Duo assigned{};
  assigned = source;
  if (std::get<Point>(fromPair).y != 19 ||
      std::get<Array>(fromPair)[1] != 21 ||
      std::get<Point>(assigned).x != 18 ||
      std::get<Array>(assigned)[0] != 20)
    return 4;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 231u);
  bool FoundArray = false, FoundTuple = false, FoundUtility = false;
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
    FoundArray |= Dependency->getString("root") == "libcxx" &&
                  Dependency->getString("path") == "array";
    FoundTuple |= Dependency->getString("root") == "libcxx" &&
                  Dependency->getString("path") == "tuple";
    FoundUtility |= Dependency->getString("root") == "libcxx" &&
                    Dependency->getString("path") == "utility";
  }
  EXPECT_TRUE(FoundArray);
  EXPECT_TRUE(FoundTuple);
  EXPECT_TRUE(FoundUtility);

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("tuple-composite" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

