TEST_F(TranslateTest,
       CoreV2MemoryByteAllocatorRuntimeCountsRunAtBothOptimizations) {
  const std::string Program = R"cpp(
using Size = decltype(sizeof(0));
extern "C" void *malloc(Size);
extern "C" void free(void *);

Size allocated_size;
Size released_size;
int allocations;
int releases;
unsigned long long effects;
int receiver_calls;
int count_calls;
int hint_calls;
int pointer_calls;
int conversion_calls;
int cleanup_calls;

// Only tiny allocations are executed by main. The source-owned allocator
// retries allocation failure and supplies a distinct byte for zero-size calls;
// neither choice is synthesized by the translator.
void *operator new(Size size) {
  ++allocations;
  allocated_size = size;
  effects = effects * 10 + 4;
  void *pointer = malloc(size ? size : Size(1));
  while (!pointer)
    pointer = malloc(size ? size : Size(1));
  return pointer;
}
void operator delete(void *pointer) noexcept {
  ++releases;
  effects = effects * 10 + 5;
  free(pointer);
}
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
void operator delete(void *pointer, Size size) noexcept {
  ++releases;
  released_size = size;
  effects = effects * 10 + 5;
  free(pointer);
}
#endif

#include <cstddef>
#include <memory>

std::allocator<char> &receiver(std::allocator<char> &allocator) {
  ++receiver_calls;
  effects = effects * 10 + 1;
  return allocator;
}
Size count(Size value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
int signed_count(int value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
struct RuntimeCount {
  Size value;
  operator Size() const {
    ++conversion_calls;
    effects = effects * 10 + 2;
    return value;
  }
  ~RuntimeCount() {
    ++cleanup_calls;
    effects = effects * 10 + 6;
  }
};
const void *hint() {
  ++hint_calls;
  effects = effects * 10 + 3;
  return nullptr;
}
char *pointer(char *value) {
  ++pointer_calls;
  effects = effects * 10 + 3;
  return value;
}
void reset_effects() {
  effects = receiver_calls = count_calls = hint_calls = pointer_calls = 0;
  conversion_calls = cleanup_calls = 0;
}

int member_checks(Size requested) {
  std::allocator<char> allocator;
  reset_effects();
  char *first = receiver(allocator).allocate(count(requested));
  if (!first || allocated_size != requested || effects != 124 ||
      receiver_calls != 1 || count_calls != 1)
    return 1;
  for (Size i = 0; i != requested; ++i)
    allocator.construct(first + i, static_cast<char>(i + 1));
  for (Size i = 0; i != requested; ++i)
    if (first[i] != static_cast<char>(i + 1))
      return 2;
  for (Size i = 0; i != requested; ++i)
    allocator.destroy(first + i);
  reset_effects();
  receiver(allocator).deallocate(pointer(first), count(requested));
  if ((effects != 1325 && effects != 1235) || receiver_calls != 1 ||
      pointer_calls != 1 || count_calls != 1)
    return 3;
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
  if (released_size != requested)
    return 4;
#endif

  reset_effects();
  char *second = receiver(allocator).allocate(count(requested + 1), hint());
  if (!second || allocated_size != requested + 1 ||
      (effects != 1234 && effects != 1324) ||
      receiver_calls != 1 || count_calls != 1 || hint_calls != 1)
    return 5;
  allocator.construct(second, 'x');
  if (*second != 'x')
    return 6;
  allocator.destroy(second);
  allocator.deallocate(second, requested + 1);

  Size zero = requested - requested;
  int before = allocations;
  reset_effects();
  char *empty = receiver(allocator).allocate(count(zero), hint());
  if (!empty || allocated_size != 0 || allocations != before + 1 ||
      receiver_calls != 1 || count_calls != 1 || hint_calls != 1)
    return 7;
  allocator.deallocate(empty, zero);
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
  if (released_size != 0)
    return 8;
#endif
  return 0;
}

int traits_checks(Size requested) {
  std::allocator<char> allocator;
  using Traits = std::allocator_traits<std::allocator<char>>;
  reset_effects();
  char *first = Traits::allocate(receiver(allocator), count(requested));
  if (!first || allocated_size != requested || receiver_calls != 1 ||
      count_calls != 1 || effects % 10 != 4)
    return 11;
  Traits::construct(allocator, first, 'y');
  if (*first != 'y')
    return 12;
  Traits::destroy(allocator, first);
  reset_effects();
  Traits::deallocate(receiver(allocator), pointer(first), count(requested));
  if (receiver_calls != 1 || pointer_calls != 1 || count_calls != 1 ||
      effects % 10 != 5)
    return 13;
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
  if (released_size != requested)
    return 14;
#endif

  reset_effects();
  char *second = Traits::allocate(receiver(allocator), count(requested + 2),
                                  hint());
  if (!second || allocated_size != requested + 2 || receiver_calls != 1 ||
      count_calls != 1 || hint_calls != 1 || effects % 10 != 4)
    return 15;
  Traits::deallocate(allocator, second, requested + 2);
  return 0;
}

struct ByteRecord { unsigned char value; };
static_assert(sizeof(ByteRecord) == 1);
static_assert(sizeof(bool) == 1);
static_assert(sizeof(std::byte) == 1);

int element_checks(Size requested) {
  std::allocator<unsigned char> bytes;
  unsigned char *byte_values = bytes.allocate(requested);
  if (allocated_size != requested)
    return 21;
  for (Size i = 0; i != requested; ++i)
    bytes.construct(byte_values + i, static_cast<unsigned char>(i + 2));
  if (byte_values[requested - 1] != static_cast<unsigned char>(requested + 1))
    return 22;
  for (Size i = 0; i != requested; ++i)
    bytes.destroy(byte_values + i);
  bytes.deallocate(byte_values, requested);

  std::allocator<bool> flags;
  bool *flag_values = flags.allocate(requested);
  if (allocated_size != requested)
    return 23;
  for (Size i = 0; i != requested; ++i)
    flags.construct(flag_values + i, i != 0);
  if (flag_values[0] || !flag_values[requested - 1])
    return 24;
  for (Size i = 0; i != requested; ++i)
    flags.destroy(flag_values + i);
  flags.deallocate(flag_values, requested);

  std::allocator<ByteRecord> records;
  ByteRecord *record_values = records.allocate(requested);
  if (allocated_size != requested)
    return 25;
  for (Size i = 0; i != requested; ++i) {
    records.construct(record_values + i);
    record_values[i].value = static_cast<unsigned char>(i + 3);
  }
  if (record_values[requested - 1].value !=
      static_cast<unsigned char>(requested + 2))
    return 26;
  for (Size i = 0; i != requested; ++i)
    records.destroy(record_values + i);
  records.deallocate(record_values, requested);

  std::allocator<std::byte> standard_bytes;
  using ByteTraits = std::allocator_traits<std::allocator<std::byte>>;
  std::byte *standard_values = ByteTraits::allocate(standard_bytes, requested,
                                                  nullptr);
  if (allocated_size != requested)
    return 27;
  ByteTraits::construct(standard_bytes, standard_values,
                        static_cast<std::byte>(42));
  if (std::to_integer<int>(*standard_values) != 42)
    return 28;
  ByteTraits::destroy(standard_bytes, standard_values);
  ByteTraits::deallocate(standard_bytes, standard_values, requested);
  return 0;
}

int conversion_checks(int requested) {
  std::allocator<char> allocator;
  const Size expected = static_cast<Size>(requested);
  reset_effects();
  char *signed_values = receiver(allocator).allocate(signed_count(requested));
  if (!signed_values || allocated_size != expected || effects != 124 ||
      receiver_calls != 1 || count_calls != 1)
    return 41;
  allocator.construct(signed_values, 's');
  if (*signed_values != 's')
    return 42;
  allocator.destroy(signed_values);
  allocator.deallocate(signed_values, requested);
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
  if (released_size != expected)
    return 43;
#endif

  reset_effects();
  char *converted_values =
      receiver(allocator).allocate(RuntimeCount{expected + 1});
  // The conversion precedes allocation, and the temporary's destructor runs
  // at the end of the full expression, after allocation but before this check.
  if (!converted_values || allocated_size != expected + 1 || effects != 1246 ||
      receiver_calls != 1 || conversion_calls != 1 || cleanup_calls != 1)
    return 44;
  allocator.construct(converted_values, 'c');
  if (*converted_values != 'c')
    return 45;
  allocator.destroy(converted_values);
  allocator.deallocate(converted_values, expected + 1);
  if (conversion_calls != 1 || cleanup_calls != 1)
    return 46;
#if defined(NEVERC_BYTE_ALLOCATOR_SIZED_DELETE)
  if (released_size != expected + 1)
    return 47;
#endif
  return 0;
}

// These exported bodies are translation/protocol controls, never invoked by
// main. The original conversion to target size_t must remain present; there is
// no pre-conversion negative-length rejection for std::allocator<char>.
extern "C" char *signed_byte_count(int requested) {
  std::allocator<char> allocator;
  return allocator.allocate(requested);
}
extern "C" char *maximum_byte_count() {
  std::allocator<char> allocator;
  return allocator.allocate(Size(-1));
}
extern "C" char *maximum_traits_byte_count() {
  std::allocator<char> allocator;
  using Traits = std::allocator_traits<std::allocator<char>>;
  return Traits::allocate(allocator, ~Size(0), nullptr);
}

int main() {
  int result = member_checks(5);
  if (result)
    return result;
  result = traits_checks(7);
  if (result)
    return result;
  result = element_checks(3);
  if (result)
    return result;
  result = conversion_checks(4);
  if (result)
    return result;
  return allocations == 11 && releases == 11 ? 0 : 31;
}
)cpp";
  for (bool Sized : {false, true}) {
    const std::string Variant = Sized ? "sized" : "unsized";
    SCOPED_TRACE(Variant);
    const auto Source = tmpFile("memory-byte-allocator-" + Variant + ".cpp");
    const auto Output = tmpFile("memory-byte-allocator-" + Variant + ".nc");
    writeFile(Source,
              (Sized ? "#define NEVERC_BYTE_ALLOCATOR_SIZED_DELETE 1\n" : "") +
                  Program);
    auto Result =
        translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
    EXPECT_NE(readFile(Output).find(
                  "translated memory lifetimes require may_alias support"),
              std::string::npos);
    for (const std::string &Optimization : {"-O0", "-O2"}) {
      SCOPED_TRACE(Optimization);
      const auto Executable =
          tmpFile("memory-byte-allocator-" + Variant + Optimization);
      auto Compile = compileGenerated(Output, Executable, Optimization);
      ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
      auto Run = exec(Executable.string(), {});
      EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
    }
  }
}

TEST_F(TranslateTest,
       CoreV2MemoryNarrowAllocatorRuntimeCountsRunAtBothOptimizations) {
  const std::string Program = R"cpp(
using Size = decltype(sizeof(0));
extern "C" void *malloc(Size);
extern "C" void free(void *);
Size allocated_size;
Size released_size;
int allocations;
int releases;
int effects;
int receiver_calls;
int count_calls;
int hint_calls;
int pointer_calls;
int conversion_calls;
int cleanup_calls;

// main executes only small requests. These source-defined allocation choices
// preserve a visible call for size zero and retry allocation failure.
void *operator new(Size size) {
  ++allocations;
  allocated_size = size;
  effects = effects * 10 + 4;
  void *result = malloc(size ? size : Size(1));
  while (!result)
    result = malloc(size ? size : Size(1));
  return result;
}
void operator delete(void *pointer) noexcept {
  ++releases;
  effects = effects * 10 + 5;
  free(pointer);
}
#if defined(NEVERC_NARROW_ALLOCATOR_SIZED_DELETE)
void operator delete(void *pointer, Size size) noexcept {
  ++releases;
  released_size = size;
  effects = effects * 10 + 5;
  free(pointer);
}
#endif

#include <memory>
using Allocator = std::allocator<int>;
using Traits = std::allocator_traits<Allocator>;
Allocator &receiver(Allocator &allocator) {
  ++receiver_calls;
  effects = effects * 10 + 1;
  return allocator;
}
unsigned char byte_count(unsigned char value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
unsigned short short_count(unsigned short value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
bool bool_count(bool value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
int signed_count(int value) {
  ++count_calls;
  effects = effects * 10 + 2;
  return value;
}
const void *hint() {
  ++hint_calls;
  effects = effects * 10 + 3;
  return nullptr;
}
int *pointer(int *value) {
  ++pointer_calls;
  effects = effects * 10 + 3;
  return value;
}
void reset_effects() {
  effects = receiver_calls = count_calls = hint_calls = pointer_calls = 0;
  conversion_calls = cleanup_calls = 0;
}
struct NarrowCount {
  unsigned char value;
  operator unsigned char() const {
    ++conversion_calls;
    effects = effects * 10 + 2;
    return value;
  }
  ~NarrowCount() {
    ++cleanup_calls;
    effects = effects * 10 + 6;
  }
};

int member_checks(unsigned char requested) {
  Allocator allocator;
  reset_effects();
  int *first = receiver(allocator).allocate(byte_count(requested));
  if (!first || allocated_size != Size(requested) * sizeof(int) ||
      effects != 124 || receiver_calls != 1 || count_calls != 1)
    return 1;
  for (Size i = 0; i != requested; ++i)
    allocator.construct(first + i, int(i + 1));
  for (Size i = 0; i != requested; ++i)
    if (first[i] != int(i + 1))
      return 2;
  for (Size i = 0; i != requested; ++i)
    allocator.destroy(first + i);
  reset_effects();
  receiver(allocator).deallocate(pointer(first), byte_count(requested));
  if ((effects != 1325 && effects != 1235) || receiver_calls != 1 ||
      pointer_calls != 1 || count_calls != 1)
    return 3;
#if defined(NEVERC_NARROW_ALLOCATOR_SIZED_DELETE)
  if (released_size != Size(requested) * sizeof(int))
    return 4;
#endif

  reset_effects();
  int *second = receiver(allocator).allocate(short_count(requested), hint());
  if (!second || allocated_size != Size(requested) * sizeof(int) ||
      (effects != 1234 && effects != 1324) ||
      receiver_calls != 1 || count_calls != 1 || hint_calls != 1)
    return 5;
  allocator.construct(second, 23);
  if (*second != 23)
    return 6;
  allocator.destroy(second);
  allocator.deallocate(second, requested);

  unsigned char zero = 0;
  int before = allocations;
  reset_effects();
  int *empty = receiver(allocator).allocate(byte_count(zero));
  if (!empty || allocated_size != 0 || allocations != before + 1 ||
      effects != 124 || receiver_calls != 1 || count_calls != 1)
    return 7;
  allocator.deallocate(empty, zero);
#if defined(NEVERC_NARROW_ALLOCATOR_SIZED_DELETE)
  if (released_size != 0)
    return 8;
#endif
  return 0;
}

int traits_checks(unsigned short requested) {
  Allocator allocator;
  reset_effects();
  int *first = Traits::allocate(receiver(allocator), short_count(requested));
  if (!first || allocated_size != Size(requested) * sizeof(int) ||
      receiver_calls != 1 || count_calls != 1 ||
      (effects != 124 && effects != 214))
    return 11;
  Traits::construct(allocator, first, 31);
  if (*first != 31)
    return 12;
  Traits::destroy(allocator, first);
  reset_effects();
  Traits::deallocate(receiver(allocator), pointer(first), short_count(requested));
  if (receiver_calls != 1 || count_calls != 1 || pointer_calls != 1 ||
      effects % 10 != 5)
    return 13;
#if defined(NEVERC_NARROW_ALLOCATOR_SIZED_DELETE)
  if (released_size != Size(requested) * sizeof(int))
    return 14;
#endif

  reset_effects();
  int *second = Traits::allocate(receiver(allocator), short_count(requested), hint());
  if (!second || allocated_size != Size(requested) * sizeof(int) ||
      receiver_calls != 1 || count_calls != 1 || hint_calls != 1 ||
      effects % 10 != 4)
    return 15;
  Traits::deallocate(allocator, second, requested);
  return 0;
}

int conversion_checks(bool present, int signed_value) {
  Allocator allocator;
  reset_effects();
  int *one = receiver(allocator).allocate(bool_count(present));
  if (!one || allocated_size != Size(present) * sizeof(int) ||
      effects != 124 || receiver_calls != 1 || count_calls != 1)
    return 21;
  allocator.deallocate(one, Size(present));

  // The actual explicitly narrowed result is 255 for the executed -1 input.
  // Do not trace past this cast and reason about the original signed value.
  reset_effects();
  int *narrowed = receiver(allocator).allocate(
      static_cast<unsigned char>(signed_count(signed_value)));
  const unsigned char actual = static_cast<unsigned char>(signed_value);
  if (!narrowed || allocated_size != Size(actual) * sizeof(int) ||
      effects != 124 || receiver_calls != 1 || count_calls != 1)
    return 22;
  allocator.construct(narrowed, 37);
  allocator.construct(narrowed + actual - 1, 41);
  if (narrowed[0] != 37 || narrowed[actual - 1] != 41)
    return 23;
  allocator.destroy(narrowed + actual - 1);
  allocator.destroy(narrowed);
  allocator.deallocate(narrowed, actual);

  unsigned char incremented = 255;
  reset_effects();
  int *postfix = receiver(allocator).allocate(incremented++);
  if (!postfix || incremented != 0 || allocated_size != Size(255) * sizeof(int) ||
      effects != 14 || receiver_calls != 1)
    return 24;
  allocator.deallocate(postfix, 255);

  const unsigned char constant_qualified = 3;
  reset_effects();
  int *qualified = receiver(allocator).allocate(byte_count(constant_qualified));
  if (!qualified || allocated_size != Size(3) * sizeof(int) ||
      effects != 124 || receiver_calls != 1 || count_calls != 1)
    return 25;
  allocator.deallocate(qualified, constant_qualified);

  reset_effects();
  int *converted = receiver(allocator).allocate(NarrowCount{3});
  if (!converted || allocated_size != Size(3) * sizeof(int) ||
      effects != 1246 || receiver_calls != 1 || conversion_calls != 1 ||
      cleanup_calls != 1)
    return 26;
  allocator.deallocate(converted, 3);
  return 0;
}

// Protocol-only exports isolate the count conversion and allocation dispatch.
// main does not call these controls, so they allocate no runtime storage.
extern "C" int *narrow_byte_count(unsigned char value) {
  Allocator allocator;
  return allocator.allocate(value);
}
extern "C" int *narrow_short_traits_count(unsigned short value) {
  Allocator allocator;
  return Traits::allocate(allocator, value, nullptr);
}
extern "C" int *narrow_boolean_count(bool value) {
  Allocator allocator;
  return allocator.allocate(value);
}
extern "C" int *narrow_postconversion_count(int value) {
  Allocator allocator;
  return allocator.allocate(static_cast<unsigned char>(value));
}

int main() {
  int result = member_checks(3);
  if (result)
    return result;
  result = traits_checks(5);
  if (result)
    return result;
  result = conversion_checks(true, -1);
  if (result)
    return result;
  reset_effects();
  Allocator allocator;
  bool zero = false;
  int before = allocations;
  int *empty = Traits::allocate(receiver(allocator), bool_count(zero), hint());
  if (!empty || allocated_size != 0 || allocations != before + 1 ||
      receiver_calls != 1 || count_calls != 1 || hint_calls != 1)
    return 31;
  Traits::deallocate(allocator, empty, zero);
  return allocations == 11 && releases == 11 ? 0 : 32;
}
)cpp";
  for (bool Sized : {false, true}) {
    const std::string Variant = Sized ? "sized" : "unsized";
    SCOPED_TRACE(Variant);
    const auto Source = tmpFile("memory-narrow-allocator-" + Variant + ".cpp");
    const auto Output = tmpFile("memory-narrow-allocator-" + Variant + ".nc");
    writeFile(Source,
              (Sized ? "#define NEVERC_NARROW_ALLOCATOR_SIZED_DELETE 1\n" : "") +
                  Program);
    auto Result =
        translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
    EXPECT_NE(readFile(Output).find(
                  "translated memory lifetimes require may_alias support"),
              std::string::npos);
    for (const std::string &Optimization : {"-O0", "-O2"}) {
      SCOPED_TRACE(Optimization);
      const auto Executable =
          tmpFile("memory-narrow-allocator-" + Variant + Optimization);
      auto Compile = compileGenerated(Output, Executable, Optimization);
      ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
      auto Run = exec(Executable.string(), {});
      EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
    }
  }
}

