  return points.first.y == 28 && points.second[0] == 29 && get<0>(moved) == 30 && get<1>(moved) == 31.5 && get<0>(cat) == 34 && get<1>(cat) == 35 && get<2>(cat) == 32 && get<3>(cat) == 33 && hidden() == 19 && calls == 3 && defaults == 1 && live == 0 && destroyed == 1 ? 0 : 11;
