TEST_F(TranslateTest, CoreV2IteratorPointerOperationsRunAtBothOptimizations) {
  const auto Source = tmpFile("iterator-operations.cpp");
  const auto Output = tmpFile("iterator-operations.nc");
  writeFile(Source, R"cpp(
#include <array>
#include <iterator>
int main() {
  int native[4]{1, 2, 3, 4};
  std::array<int, 4> boxed{{5, 6, 7, 8}};
  int effects = 0;
  if (std::begin((++effects, native)) != native || effects != 1)
    return 1;
  if (std::end((++effects, native)) - native != 4 || effects != 2)
    return 2;
  if (std::size((++effects, native)) != 4 || effects != 3)
    return 3;
  bool native_empty = std::empty((++effects, native));
  if (native_empty || effects != 4)
    return 4;
  if (std::data((++effects, native)) != native || effects != 5)
    return 5;
  if (std::cbegin(native)[1] != 2 || std::cend(native)[-1] != 4)
    return 6;

  if (std::begin((++effects, boxed)) != boxed.data() || effects != 6)
    return 7;
  if (std::end((++effects, boxed)) - boxed.data() != 4 || effects != 7)
    return 8;
  if (std::size((++effects, boxed)) != 4 || effects != 8)
    return 9;
  bool boxed_empty = std::empty((++effects, boxed));
  if (boxed_empty || effects != 9)
    return 10;
  if (std::data((++effects, boxed))[2] != 7 || effects != 10)
    return 11;
  const std::array<int, 4> &view = boxed;
  if (std::cbegin(view)[1] != 6 || std::cend(view)[-1] != 8 ||
      std::distance(std::cbegin(view), std::cend(view)) != 4)
    return 12;

  int *first = std::begin(native);
  int *last = std::end(native);
  std::advance(first, static_cast<short>(2));
  if (*first != 3)
    return 13;
  std::advance(first, -1);
  if (*first != 2 || std::distance(first, last) != 3)
    return 14;
  if (*std::next(first) != 3 || *std::next(first, 2) != 4 ||
      *std::prev(last) != 4 || *std::prev(last, 2) != 3)
    return 15;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 228u);
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
  }

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("iterator-operations" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2ReverseIteratorOperationsRunAtBothOptimizations) {
  const auto Source = tmpFile("reverse-iterator-operations.cpp");
  const auto Output = tmpFile("reverse-iterator-operations.nc");
  writeFile(Source, R"cpp(
#include <array>
#include <iterator>
static_assert(sizeof(std::reverse_iterator<int *>) == 2 * sizeof(void *));
int main() {
  int native[5]{1, 2, 3, 4, 5};
  int effects = 0;
  auto begin = std::rbegin((++effects, native));
  auto end = std::rend((++effects, native));
  if (effects != 2 || *begin != 5 || begin.base() != native + 5 ||
      begin.operator->() != native + 4)
    return 1;
  auto old = begin++;
  if (*old != 5 || *begin != 4)
    return 2;
  ++begin;
  if (*begin != 3)
    return 3;
  auto before = begin--;
  if (*before != 3 || *begin != 4)
    return 4;
  --begin;
  if (*begin != 5)
    return 5;
  if (*(begin + 2) != 3 || *(2 + begin) != 3 || (begin + 2)[1] != 2)
    return 6;
  begin += 3;
  if (*begin != 2)
    return 7;
  begin -= 2;
  if (*begin != 4)
    return 8;
  if (!(begin != end) || begin == end || !(begin < end) || begin > end ||
      !(begin <= end) || begin >= end || end - begin != 4)
    return 9;

  auto made = std::make_reverse_iterator(native + 5);
  std::reverse_iterator<int *> empty;
  std::reverse_iterator<int *> direct(native + 5);
  std::reverse_iterator<int *> copied(direct);
  std::reverse_iterator<const int *> converted(direct);
  converted = copied;
  copied = direct;
  if (empty.base() != nullptr || *made != 5 || *copied != 5 ||
      *converted != 5)
    return 10;

  const int (&view)[5] = native;
  if (*std::crbegin(view) != 5 || std::crend(view).base() != native)
    return 11;
  std::array<int, 3> boxed{{6, 7, 8}};
  if (*((++effects, boxed).rbegin()) != 8 || effects != 3 ||
      *boxed.crbegin() != 8 || boxed.rend().base() != boxed.begin() ||
      boxed.crend().base() != boxed.cbegin() || *std::rbegin(boxed) != 8 ||
      std::rend(boxed).base() != boxed.begin())
    return 12;

  auto algorithm = std::rbegin(native);
  std::advance(algorithm, static_cast<short>(2));
  if (*algorithm != 3 || std::distance(algorithm, std::rend(native)) != 3 ||
      *std::next(algorithm) != 2 || *std::next(algorithm, 2) != 1 ||
      *std::prev(algorithm) != 4 || *std::prev(std::rend(native)) != 1)
    return 13;
  return 0;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;

  auto Manifest =
      llvm::json::parse(readFile(fs::path(Output.string() + ".manifest.json")));
  ASSERT_TRUE(static_cast<bool>(Manifest))
      << llvm::toString(Manifest.takeError()).str().str();
  const auto *SDK = Manifest->getAsObject()->getObject("sdk");
  ASSERT_NE(SDK, nullptr);
  const auto *Dependencies = SDK->getArray("dependencies");
  ASSERT_NE(Dependencies, nullptr);
  EXPECT_EQ(Dependencies->size(), 228u);
  for (const auto &Entry : *Dependencies) {
    const auto *Dependency = Entry.getAsObject();
    ASSERT_NE(Dependency, nullptr);
    EXPECT_NE(Dependency->getString("root"), "platform");
  }

  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("reverse-iterator-operations" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

