    const auto Output = tmpFile(std::string("user-object-invoke-query-reject-") +
                                Case.Name + ".nc");
    writeFile(Source, R"cpp(#include <functional>
#include <type_traits>
#include <utility>
struct F{int operator()(int n)const noexcept{return n;}};
)cpp" + std::string(Case.Source));
