TEST_F(TranslateTest, CoreV2InheritedConstMoveDefaultMoveIfNoexceptQueriesRunAtBothOptimizations) {
  const auto Source = tmpFile("inherited-const-move-default-move-if-noexcept-queries.cpp");
  const auto Output = tmpFile("inherited-const-move-default-move-if-noexcept-queries.nc");
  writeFile(Source, R"cpp(
#include <utility>
namespace Imported { using std::move_if_noexcept; }
namespace Reexport { using Imported::move_if_noexcept; }
namespace Alias = Reexport;
int created, copies, defaults, cleanups, sum, calls, operand_defaults, referent=9;
int nt_copies, nt_defaults, nt_cleanups, nt_sum;
struct Seed { int value; };
Seed seed{1};
template<class T> T &source(T &v, int n=(++operand_defaults,1)) noexcept { ++calls; return v; }
template<class Result, class T> bool queries(T &v) {
  using Alias::move_if_noexcept;
  static_assert(__is_same(decltype(move_if_noexcept(v)),Result));
  static_assert(__is_same(decltype((Imported::move_if_noexcept)(v)),Result));
  static_assert(__is_same(decltype(move_if_noexcept<T>(v)),Result));
  static_assert(sizeof(move_if_noexcept(v))==sizeof(T));
  static_assert(alignof(decltype(move_if_noexcept(v)))==alignof(T));
  static_assert(noexcept(move_if_noexcept(v)));
  Result alias=move_if_noexcept(std::forward<T&>(v));
  return &alias==&v;
}
template<class T> struct Cell {
  T value;
  Cell(T n=7) noexcept : value(n) { ++created; }
  Cell(const Cell&o, Seed &s=(++defaults,seed)) noexcept(false)
      : value(o.value+s.value) { ++s.value; ++copies; }
  Cell(Cell&&, T=T::missing, int(&)[2]=T::missing, Seed=T::missing) noexcept {
    static_assert(sizeof(T)==0);
  }
  ~Cell() noexcept { ++cleanups; sum+=value; }
};
using Item=Cell<int>;
struct Owner { Item value; int &link=referent; int *pointer=&referent; };
struct Nested { Owner values[2]; };
struct Written {
  Cell<int> value;
  Written()=default;
  Written(const Written&)=default;
  Written(Written&&)=default;
};
using Row=Cell<int>[2];
struct Matrix { Row values[2]; };
struct Frozen { const Nested value; };
template<class T> struct Nothrow {
  T value;
  Nothrow(T n=20) noexcept : value(n) {}
  Nothrow(const Nothrow&o, int n=(++nt_defaults,2)) noexcept : value(o.value+n) { ++nt_copies; }
  Nothrow(Nothrow&&,T=T::missing) noexcept { static_assert(sizeof(T)==0); }
  ~Nothrow() noexcept { ++nt_cleanups; nt_sum+=value; }
};
struct NothrowOwner { Nothrow<int> value; };
template<class T> struct Lazy {
  T value=T::missing;
  Lazy(const Lazy&) noexcept(false) { static_assert(sizeof(T)==0); }
  Lazy(Lazy&&,T=T::missing) noexcept { static_assert(sizeof(T)==0); }
  ~Lazy() noexcept { static_assert(sizeof(T)==0); }
};
struct LazyOwner { Lazy<int> value; };
struct CopyOnly { Lazy<long> value; CopyOnly(const CopyOnly&)=default; };
struct FriendOwner;
template<class T> class Locked {
  friend struct FriendOwner;
  Locked(Locked&&,Seed &s=T::missing) noexcept { static_assert(sizeof(T)==0); }
public:
  T value;
  Locked(const Locked&) noexcept(false) { static_assert(sizeof(T)==0); }
};
struct FriendOwner { Locked<int> value; };
template<class T> struct Redeclared {
  T value;
  Redeclared(const Redeclared&) noexcept(false) { static_assert(sizeof(T)==0); }
  Redeclared(Redeclared&&,T=T::missing) noexcept;
};
template<class T> Redeclared<T>::Redeclared(Redeclared&&,T) noexcept { static_assert(sizeof(T)==0); }
struct RedeclaredOwner { Redeclared<int> value; };
int query_only(const LazyOwner&a, const CopyOnly&b, const FriendOwner&c, const RedeclaredOwner&d) {
  return queries<const LazyOwner&>(a) && queries<const CopyOnly&>(b) &&
         queries<const FriendOwner&>(c) && queries<const RedeclaredOwner&>(d);
}
int main() {
  {
    Owner a;
    Nested n;
    Written w;
    Matrix m;
    Frozen frozen;
    static_assert(__is_same(decltype(Alias::move_if_noexcept(source(std::as_const(a)))),const Owner&));
    static_assert(sizeof(Alias::move_if_noexcept(source(std::as_const(a))))==sizeof(a));
    static_assert(noexcept(Alias::move_if_noexcept(source(std::as_const(a)))));
    if (!queries<const Owner&>(std::as_const(a)) ||
        !queries<const Nested&>(std::as_const(n)) ||
        !queries<const Written&>(std::as_const(w)) ||
        !queries<const Matrix&>(std::as_const(m))) return 1;
    const Owner &explicit_const=Alias::move_if_noexcept<const Owner>(a);
    if (&explicit_const!=&a) return 11;
    if (created!=10 || copies || defaults || cleanups || calls || operand_defaults) return 2;
    const Owner &alias=Alias::move_if_noexcept(source(std::as_const(a)));
    ++alias.link;
    if (&alias!=&a || alias.pointer!=&referent || referent!=10 || calls!=1 || operand_defaults!=1) return 3;
    Owner ca(Alias::move_if_noexcept(std::as_const(a)));
    Nested cn(Alias::move_if_noexcept(std::as_const(n)));
    Written cw(Alias::move_if_noexcept(std::as_const(w)));
    Matrix cm(Alias::move_if_noexcept(std::as_const(m)));
    if (ca.value.value!=8 || cn.values[0].value.value!=9 || cn.values[1].value.value!=10 || cw.value.value!=11 ||
        cm.values[0][0].value!=12 || cm.values[0][1].value!=13 ||
        cm.values[1][0].value!=14 || cm.values[1][1].value!=15 ||
        &ca.link!=&referent || ca.pointer!=&referent || copies!=8 || defaults!=8 || seed.value!=9 || cleanups) return 4;
    // A const xvalue still selects the owner's copy.
    Owner moved(std::move(std::as_const(a)));
    if (moved.value.value!=16 || a.value.value!=7 || n.values[1].value.value!=7 ||
        w.value.value!=7 || m.values[1][1].value!=7 || copies!=9 || defaults!=9 || seed.value!=10) return 5;
    if (!queries<const Frozen&>(frozen) || !queries<const Frozen&>(std::as_const(frozen))) return 6;
    Frozen copied_frozen(Alias::move_if_noexcept(frozen));
    if (copied_frozen.value.values[0].value.value!=17 || copied_frozen.value.values[1].value.value!=18 ||
        frozen.value.values[0].value.value!=7 || copies!=11 || defaults!=11 || seed.value!=12) return 7;
    NothrowOwner nt;
    if (!queries<const NothrowOwner&&>(std::as_const(nt)) ||
        nt_copies || nt_defaults || nt_cleanups) return 8;
    NothrowOwner nm(Alias::move_if_noexcept<const NothrowOwner>(nt));
    NothrowOwner nc(Alias::move_if_noexcept(std::as_const(nt)));
    if (nt.value.value!=20 || nm.value.value!=22 || nc.value.value!=22 || nt_copies!=2 || nt_defaults!=2) return 9;
  }
  return created==10 && copies==11 && defaults==11 && cleanups==21 && sum==213 &&
         calls==1 && operand_defaults==1 && nt_copies==2 && nt_defaults==2 && nt_cleanups==3 && nt_sum==64 ? 0 : 10;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  EXPECT_EQ(readFile(Output).find("std::"), std::string::npos);
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("inherited-const-move-default-move-if-noexcept-queries" + Optimization);
    auto Compile =
        compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

