TEST_F(TranslateTest, CoreV2FunctionalStoredMemFnRunsAtBothOptimizations) {
  const auto Source = tmpFile("functional-stored-mem-fn.cpp");
  const auto Output = tmpFile("functional-stored-mem-fn.nc");
  writeFile(Source, R"cpp(
#include <functional>
#include <utility>
struct Box {
  int value;
  const int fixed;
  int *link;
  int add(short n) const { return value + n; }
  int *pass(int *pointer) const { return pointer; }
  void set(int n) { value = n; }
  void redirect(int *&pointer) const { pointer = link; }
  int &slot() { return value; }
};
int main() {
  int first = 17;
  int second = 19;
  Box box{3, 8, &first};
  const Box constant{5, 13, &second};
  auto value = std::mem_fn(&Box::value);
  const auto value_copy = value;
  auto value_chain = std::move(value_copy);
  auto fixed = std::mem_fn(&Box::fixed);
  auto link = std::mem_fn(&Box::link);
  auto add = std::mem_fn(&Box::add);
  auto add_move = std::move(add);
  auto add_forward = std::forward<decltype(add_move)>(add_move);
  auto add_conditional = std::move_if_noexcept(add_forward);
  auto add_chain = std::as_const(add_conditional);
  auto pass = std::mem_fn(&Box::pass);
  auto set = std::mem_fn(&Box::set);
  auto set_copy = set;
  auto redirect = std::mem_fn(&Box::redirect);
  auto slot = std::mem_fn(&Box::slot);
  auto slot_copy = slot;
  std::move(value_chain)(box) = 7;
  int score = 0;
  score += std::as_const(value)(&box) == 7;
  score += std::invoke(std::move_if_noexcept(fixed), constant) == 13;
  score += std::forward<decltype(link)>(link)(std::cref(constant)) == &second;
  std::invoke(std::as_const(link), std::ref(box)) = &second;
  score += box.link == &second;
  set_copy(&box, 9);
  score += box.value == 9;
  slot_copy(std::ref(box)) = 11;
  score += box.value == 11;
  int *cursor = &first;
  std::invoke(redirect, std::cref(constant), cursor);
  score += cursor == &second;
  score += std::move(add_chain)(box, 2) == 13;
  score += std::invoke(std::as_const(add), &constant, 1) == 6;
  score += std::move_if_noexcept(pass)(constant, &first) == &first;
  return score == 10 ? 0 : score;
}
)cpp");
  auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  const auto Generated = readFile(Output);
  EXPECT_EQ(Generated.find("std::"), std::string::npos);
  EXPECT_EQ(Generated.find("indirect_call"), std::string::npos);
  EXPECT_EQ(Generated.find("member_pointer"), std::string::npos);
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("functional-stored-mem-fn" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization);
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2FunctionalFunctionObjectsRequireExactForms) {
  struct Rejection {
    const char *Name;
    const char *Source;
    const char *Code;
  };
  const Rejection Cases[] = {
      {"qualified",
       "#include <functional>\nint main(){return "
       "std::plus<const int>{}(1,2);}",
       "TR0203"},
      {"long-double",
       "#include <functional>\nint main(){return "
       "std::plus<long double>{}(1,2)==3;}",
       "TR0201"},
      {"hash-volatile-pointer",
       "#include <functional>\nint main(){volatile int n=0;return "
       "std::hash<volatile int*>{}(&n);}",
       "TR0201"},
      {"hash-volatile-void-pointer",
       "#include <functional>\nint main(){volatile int n=0;return "
       "std::hash<volatile void*>{}(&n);}",
       "TR0201"},
      {"reference-wrapper-volatile",
       "#include <functional>\nint main(){volatile int v=0;"
       "std::reference_wrapper<volatile int> r(v);return r.get();}",
       "TR0201"},
      {"cref-temporary",
       "#include <functional>\nint main(){auto r=std::cref(3);return "
       "r.get();}",
       "TR0202"},
      {"reference-wrapper-function-volatile-reference-parameter",
       "#include <functional>\nint load(volatile int&v){return v;}int main(){"
       "auto p=&load;auto r=std::ref(p);volatile int v=3;return r(v);}",
       "TR0201"},
      {"reference-wrapper-variadic",
       "#include <functional>\nint first(int v,...){return v;}int main(){"
       "auto p=&first;auto r=std::ref(p);return r(3,4);}",
       "TR0201"},
      {"invoke-volatile-reference-parameter",
       "#include <functional>\nint load(volatile int&v){return v;}int main(){"
       "volatile int v=3;return std::invoke(load,v);}",
       "TR0201"},
      {"invoke-record-copy-with-throw",
       "#include <functional>\nstruct R{int n;R(int v):n(v){}"
       "R(const R&r):n(r.n){throw 1;}~R(){}};int load(R r){return r.n;}"
       "int main(){R r{3};return std::invoke(load,r);}",
       "TR0201"},
      {"invoke-variadic",
       "#include <functional>\nint first(int v,...){return v;}int main(){"
       "return std::invoke(first,3,4);}",
       "TR0201"},
      {"invoke-stored-member-pointer-reassignment",
       "#include <functional>\nstruct X{int a,b;};int main(){X x{3,4};"
       "auto p=&X::a;p=&X::b;return std::invoke(p,x);}",
       "TR0201"},
      {"invoke-stored-member-pointer-copy-from-parameter",
       "#include <functional>\nstruct X{int v;};"
       "int call(int X::*p,X&x){auto q=p;return std::invoke(q,x);}"
       "int main(){X x{3};return call(&X::v,x);}",
       "TR0201"},
      {"invoke-stored-member-pointer-move-from-parameter",
       "#include <functional>\n#include <utility>\nstruct X{int v;};"
       "int call(int X::*p,X&x){auto q=std::move(p);"
       "return std::invoke(q,x);}"
       "int main(){X x{3};return call(&X::v,x);}",
       "TR0201"},
      {"invoke-member-pointer-use-adapter-from-parameter",
       "#include <functional>\n#include <utility>\nstruct X{int v;};"
       "int call(int X::*p,X&x){return std::invoke(std::move(p),x);}"
       "int main(){X x{3};return call(&X::v,x);}",
       "TR0201"},
      {"invoke-null-member-pointer",
       "#include <functional>\nstruct X{int v;};int main(){X x{3};"
       "int X::*p=nullptr;return std::invoke(p,x);}",
       "TR0201"},
      {"invoke-null-member-function-pointer",
       "#include <functional>\nstruct X{int f(){return 3;}};int main(){X x;"
       "int (X::*p)()=nullptr;return std::invoke(p,x);}",
       "TR0201"},
      {"native-member-pointer-from-parameter",
       "struct X{int v;};int call(int X::*p,X&x){return x.*p;}"
       "int main(){X x{3};return call(&X::v,x);}",
       "TR0201"},
      {"native-volatile-data-member-pointer",
       "struct X{int v;};int main(){volatile X x{3};"
       "auto p=&X::v;return x.*p;}",
       "TR0201"},
      {"native-null-data-member-pointer",
       "struct X{int v;};int main(){X x{3};int X::*p=nullptr;"
       "return x.*p;}",
       "TR0201"},
      {"native-null-member-function-pointer",
       "struct X{int f(){return 3;}};int main(){X x;"
       "int(X::*p)()=nullptr;return (x.*p)();}",
       "TR0201"},
      {"native-member-function-pointer-from-parameter",
       "struct X{int f(){return 3;}};int call(int(X::*p)(),X&x){"
       "return (x.*p)();}int main(){X x;return call(&X::f,x);}",
       "TR0201"},
      {"invoke-member-volatile-receiver",
       "#include <functional>\nstruct X{int v;};int main(){volatile X x{3};"
       "return std::invoke(&X::v,x);}",
       "TR0203"},
      {"invoke-member-variadic-function-pointer-field",
       "#include <functional>\nint f(int n,...){return n;}struct X{"
       "int(*p)(int,...);};int main(){X x{f};return "
       "std::invoke(&X::p,x)(1,2);}",
       "TR0201"},
      {"stored-mem-fn-move-from-parameter",
       "#include <functional>\n#include <utility>\nstruct X{int v;};"
       "using Get=decltype(std::mem_fn(&X::v));"
       "int call(Get get,X&x){auto q=std::move(get);return q(x);}"
       "int main(){X x{3};return call(std::mem_fn(&X::v),x);}",
       "TR0203"},
      {"stored-mem-fn-use-adapter-from-parameter",
       "#include <functional>\n#include <utility>\nstruct X{int v;};"
       "using Get=decltype(std::mem_fn(&X::v));"
       "int call(Get get,X&x){return std::move(get)(x);}"
       "int main(){X x{3};return call(std::mem_fn(&X::v),x);}",
       "TR0203"},
      {"mem-fn-member-pointer-from-parameter",
       "#include <functional>\nstruct X{int v;};"
       "int call(int X::*p,X&x){auto get=std::mem_fn(p);return get(x);}"
       "int main(){X x{3};return call(&X::v,x);}",
       "TR0203"},
      {"stored-mem-fn-reassignment",
       "#include <functional>\nstruct X{int v,w;};int main(){X x{3,4};"
       "auto get=std::mem_fn(&X::v);get=std::mem_fn(&X::w);return get(x);}",
       "TR0203"},
  };
  for (const auto &Case : Cases) {
    SCOPED_TRACE(Case.Name);
    const auto Source =
        tmpFile(std::string("functional-") + Case.Name + ".cpp");
    const auto Output = tmpFile(std::string("functional-") + Case.Name + ".nc");
    writeFile(Source, Case.Source);
    expectCode(
        translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()}),
        Case.Code);
    expectNoArtifacts(Output);
  }
}

