    only.push_back(static_cast<MoveOnly &&>(only[0]));
    if (only[0].value || *only[1].value != 17 ||
        moves != moves_before_append + 1) return 12;
    only.shrink_to_fit();
    only.pop_back();
    if (only.size() != 1) return 13;
