    return 7;
  auto vector_middle = vector_cursor + 2;
  if (*(vector_middle - 1) != 20 || *vector_middle++ != 30 ||
      *vector_middle-- != 40 || *vector_middle != 30)
    return 8;
  vector_middle += 1;
  vector_middle -= 2;
