TEST_F(TranslateTest, CoreV2WrapperMergeRuntimeAlias) {
  const auto Source = tmpFile("wrapper-merge-runtime-alias.cpp");
  const auto Output = tmpFile("wrapper-merge-runtime-alias.nc");
  writeFile(Source, R"cpp(
#include <functional>
#include <algorithm>
template<class T>using Alias=std::reference_wrapper<T>;using R=Alias<int>;
int main(){int x=1,y=2,z=9;R a[]={x},b[]={y},o[]={z,z};return std::merge(a,a+1,b,b+1,o)!=o+2||&o[0].get()!=&x||&o[1].get()!=&y;}
)cpp");
  const auto Result =
      translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable =
        tmpFile("wrapper-merge-runtime-alias" + Optimization);
    const auto Compile =
        compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    const auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

